import { GoogleGenAI, Type, Modality } from "@google/genai";

// Initialize lazily to prevent crashing the whole app if the API key is missing at runtime
let aiInstance: GoogleGenAI | null = null;

const getAI = () => {
  if (!aiInstance) {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.warn("Gemini API Key is missing. Some features may not work.");
      // We still return an instance, but it will error only when called
      aiInstance = new GoogleGenAI({ apiKey: "MISSING_KEY" });
    } else {
      aiInstance = new GoogleGenAI({ apiKey });
    }
  }
  return aiInstance;
};

export const extractDevotionalStructure = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `You are a content extractor. Your goal is to take a raw devotional text and identify its components. 
      CRITICAL RULE: You MUST NOT rewrite, summarize, or refurbish the 'content' field. It must be a verbatim copy of the main body of the text provided.

      Input text: "${text}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "The title of the devotional" },
            scripture: { type: Type.STRING, description: "The specific Bible verse or reference mentioned" },
            content: { type: Type.STRING, description: "The original, untouched main body text" },
            prayer: { type: Type.STRING, description: "A concluding prayer if present, or a short one based on the text if not" },
            meditation: { type: Type.STRING, description: "A short one-sentence key takeaway" },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "scripture", "content", "prayer", "meditation", "tags"]
        }
      }
    });

    const result = JSON.parse(response.text.trim());
    return result;
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    return null;
  }
};

export const getDailyReflections = async (devotional: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Based on this devotional, provide 3 deep reflection questions to help the reader grow spiritually today: "${devotional}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Gemini Reflections Error:", error);
    return ["What stood out to you today?", "How can you apply this to your life?", "Who can you share this with?"];
  }
};

export const generateDevotionalAudio = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Read this devotional with a peaceful, reflective, and warm tone: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio || null;
  } catch (error) {
    console.error("Gemini TTS Error:", error);
    return null;
  }
};

/**
 * Utility service for handling the raw PCM audio returned by Gemini TTS
 */

function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export class SpiritAudioPlayer {
  private context: AudioContext | null = null;
  private source: AudioBufferSourceNode | null = null;
  private isPlaying: boolean = false;

  async play(base64Data: string): Promise<void> {
    if (this.source) {
      this.stop();
    }

    if (!this.context) {
      this.context = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const audioBytes = decodeBase64(base64Data);
    const audioBuffer = await decodeAudioData(audioBytes, this.context, 24000, 1);

    this.source = this.context.createBufferSource();
    this.source.buffer = audioBuffer;
    this.source.connect(this.context.destination);

    this.source.onended = () => {
      this.isPlaying = false;
    };

    this.source.start(0);
    this.isPlaying = true;
  }

  stop() {
    if (this.source) {
      try {
        this.source.stop();
      } catch (e) {
        // Source might already be stopped
      }
      this.source = null;
    }
    this.isPlaying = false;
  }

  get currentlyPlaying() {
    return this.isPlaying;
  }
}

export const audioPlayer = new SpiritAudioPlayer();

import React, { useState, useEffect, useRef } from 'react';
import { DevotionalEntry, ThemeMode } from '../types';
import { getDailyReflections, generateDevotionalAudio } from '../services/geminiService';
import { audioPlayer } from '../services/audioService';

interface Props {
  entry: DevotionalEntry;
  theme: ThemeMode;
  fontSize: string;
}

const DevotionalCard: React.FC<Props> = ({ entry, theme, fontSize }) => {
  const [reflections, setReflections] = useState<string[]>([]);
  const [loadingReflections, setLoadingReflections] = useState(false);
  const [loadingAudio, setLoadingAudio] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioDataRef = useRef<string | null>(null);

  useEffect(() => {
    const fetchReflections = async () => {
      setLoadingReflections(true);
      const res = await getDailyReflections(entry.content);
      setReflections(res);
      setLoadingReflections(false);
    };
    fetchReflections();

    // Reset audio state when entry changes
    audioDataRef.current = null;
    setIsPlaying(false);
    audioPlayer.stop();

    return () => {
      audioPlayer.stop();
    };
  }, [entry.id, entry.content]);

  const toggleAudio = async () => {
    if (isPlaying) {
      audioPlayer.stop();
      setIsPlaying(false);
      return;
    }

    if (audioDataRef.current) {
      await audioPlayer.play(audioDataRef.current);
      setIsPlaying(true);
      return;
    }

    setLoadingAudio(true);
    const fullText = `${entry.title}. Scripture reading: ${entry.scripture}. ${entry.content}. Prayer: ${entry.prayer || ''}`;
    const base64 = await generateDevotionalAudio(fullText);

    if (base64) {
      audioDataRef.current = base64;
      await audioPlayer.play(base64);
      setIsPlaying(true);
    } else {
      alert("Unable to generate audio at this time. Please try again later.");
    }
    setLoadingAudio(false);
  };

  const fontSizeClass = {
    sm: 'text-sm',
    base: 'text-base',
    lg: 'text-lg',
    xl: 'text-xl'
  }[fontSize as 'sm' | 'base' | 'lg' | 'xl'] || 'text-base';

  return (
    <div className="py-8 animate-in fade-in duration-700">
      <div className="mb-6">
        <span className="text-xs font-bold uppercase tracking-[0.2em] text-amber-800/60 block mb-2">
          {new Date(entry.date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
        </span>
        <h2 className={`text-3xl md:text-4xl font-bold leading-tight serif-font ${theme === 'dark' ? 'text-white' : 'text-stone-900'}`}>
          {entry.title}
        </h2>
      </div>

      {/* Audio Narrator Bar */}
      <div className={`mb-8 p-4 rounded-2xl flex items-center justify-between border transition-all duration-500 ${
        theme === 'dark' ? 'bg-stone-800/40 border-stone-700' : 'bg-white border-stone-100 shadow-sm'
      }`}>
        <div className="flex items-center gap-4">
          <button 
            onClick={toggleAudio}
            disabled={loadingAudio}
            className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${
              isPlaying 
                ? 'bg-amber-600 text-white scale-110 shadow-lg shadow-amber-900/20' 
                : 'bg-stone-100 text-stone-600 hover:bg-amber-50 hover:text-amber-700'
            } disabled:opacity-50`}
          >
            {loadingAudio ? (
              <div className="w-5 h-5 border-2 border-stone-400 border-t-stone-100 rounded-full animate-spin"></div>
            ) : isPlaying ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            )}
          </button>
          <div>
            <p className={`text-xs font-bold tracking-widest uppercase mb-0.5 ${theme === 'dark' ? 'text-stone-400' : 'text-stone-500'}`}>
              {isPlaying ? 'Now Narrating' : 'Spirit Voice'}
            </p>
            <p className={`serif-font text-sm ${theme === 'dark' ? 'text-stone-200' : 'text-stone-800'}`}>
              {loadingAudio ? 'Preparing narration...' : isPlaying ? 'Peaceful Reflection (Kore)' : 'Listen to this devotional'}
            </p>
          </div>
        </div>
        {isPlaying && (
          <div className="flex gap-1 items-end h-4 mr-2">
            {[1, 2, 3, 4, 3, 2].map((h, i) => (
              <div key={i} className="w-1 bg-amber-500 animate-pulse" style={{ height: `${h * 25}%`, animationDelay: `${i * 0.1}s` }}></div>
            ))}
          </div>
        )}
      </div>

      {entry.imageUrl && (
        <img 
          src={entry.imageUrl} 
          alt={entry.title} 
          className="w-full h-56 object-cover rounded-3xl shadow-xl shadow-stone-900/5 mb-8"
        />
      )}

      <div className={`p-6 rounded-2xl border-l-4 border-amber-600 mb-8 italic ${
        theme === 'dark' ? 'bg-stone-800 text-stone-300' : 'bg-amber-50 text-amber-900'
      }`}>
        <p className="font-medium">{entry.scripture}</p>
      </div>

      <article className={`serif-font leading-relaxed ${fontSizeClass} mb-12 ${
        theme === 'dark' ? 'text-stone-300' : 'text-stone-700'
      }`}>
        {entry.content.split('\n').map((para, i) => (
          <p key={i} className="mb-4">{para}</p>
        ))}
      </article>

      {entry.prayer && (
        <div className={`p-8 rounded-3xl border text-center mb-12 ${
          theme === 'dark' ? 'border-stone-800 bg-stone-800/40' : 'border-amber-100 bg-white shadow-sm'
        }`}>
          <h3 className="text-xs font-bold uppercase tracking-widest text-amber-700 mb-4">A Moment of Prayer</h3>
          <p className="text-lg italic serif-font text-stone-500">"{entry.prayer}"</p>
        </div>
      )}

      {entry.meditation && (
        <div className="border-t border-stone-200 pt-8 mb-12 text-center">
          <p className="text-amber-800/70 font-medium tracking-wide">DAILY MEDITATION</p>
          <p className="text-2xl font-light italic mt-2 serif-font">{entry.meditation}</p>
        </div>
      )}

      <section className={`p-8 rounded-3xl ${theme === 'dark' ? 'bg-stone-800/50' : 'bg-stone-100'}`}>
        <h3 className="text-lg font-semibold mb-6 flex items-center gap-2">
          Spirit Reflections
        </h3>
        {loadingReflections ? (
          <div className="space-y-4">
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-full"></div>
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-3/4"></div>
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-5/6"></div>
          </div>
        ) : (
          <ul className="space-y-6">
            {reflections.map((q, i) => (
              <li key={i} className="flex gap-4">
                <span className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-200 text-amber-800 flex items-center justify-center font-bold text-sm">
                  {i + 1}
                </span>
                <p className={`text-sm leading-relaxed ${theme === 'dark' ? 'text-stone-300' : 'text-stone-600'}`}>
                  {q}
                </p>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
};

export default DevotionalCard;

