import React, { useState } from 'react';
import { extractDevotionalStructure } from '../services/geminiService';
import { DevotionalEntry, SundaySchoolLesson } from '../types';
import { storage } from '../services/storageService';
import { ICONS } from '../constants';

const AdminPanel: React.FC<{ onEntryAdded: () => void }> = ({ onEntryAdded }) => {
  const [contentType, setContentType] = useState<'devotional' | 'sunday-school'>('devotional');
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState<'ai' | 'manual'>('ai');

  // States for organized entry
  const [devotionalEntry, setDevotionalEntry] = useState<Partial<DevotionalEntry> | null>(null);
  const [sundaySchoolEntry, setSundaySchoolEntry] = useState<Partial<SundaySchoolLesson> | null>(null);

  const handleProcess = async () => {
    if (!inputText.trim() && mode === 'ai') return;

    if (contentType === 'devotional') {
      if (mode === 'ai') {
        setLoading(true);
        const extracted = await extractDevotionalStructure(inputText);
        if (extracted) {
          setDevotionalEntry({
            ...extracted,
            date: new Date().toISOString().split('T')[0],
            id: Math.random().toString(36).substr(2, 9),
            imageUrl: `https://picsum.photos/seed/${Math.random()}/800/450`
          });
        }
        setLoading(false);
      } else {
        setDevotionalEntry({
          title: 'Untitled Entry',
          scripture: 'Add scripture here...',
          content: inputText,
          prayer: 'Add prayer here...',
          meditation: 'Add meditation here...',
          tags: [],
          date: new Date().toISOString().split('T')[0],
          id: Math.random().toString(36).substr(2, 9),
          imageUrl: `https://picsum.photos/seed/${Math.random()}/800/450`
        });
      }
    } else {
      // Sunday School manual setup
      setSundaySchoolEntry({
        id: Math.random().toString(36).substr(2, 9),
        date: new Date().toISOString().split('T')[0],
        title: 'Untitled Lesson',
        topic: 'New Topic',
        memoryVerse: 'Add memory verse...',
        content: inputText,
        discussionQuestions: ['Add a question...'],
        imageUrl: `https://picsum.photos/seed/${Math.random()}/800/450`
      });
    }
  };

  const handlePublishDevotional = () => {
    if (!devotionalEntry || !devotionalEntry.title || !devotionalEntry.content) {
      alert('Please fill in at least the title and content.');
      return;
    }
    const current = storage.getDevotionals();
    storage.saveDevotionals([devotionalEntry as DevotionalEntry, ...current]);
    setDevotionalEntry(null);
    setInputText('');
    onEntryAdded();
    alert('Devotional Published Successfully!');
  };

  const handlePublishSundaySchool = () => {
    if (!sundaySchoolEntry || !sundaySchoolEntry.title || !sundaySchoolEntry.content) {
      alert('Please fill in at least the title and content.');
      return;
    }
    const current = storage.getSundaySchool();
    storage.saveSundaySchool([sundaySchoolEntry as SundaySchoolLesson, ...current]);
    setSundaySchoolEntry(null);
    setInputText('');
    onEntryAdded();
    alert('Sunday School Lesson Published Successfully!');
  };

  return (
    <div className="space-y-6 pt-6 animate-in fade-in slide-in-from-top-4">
      {/* Type & Mode Selection */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-stone-200">
        <h2 className="text-xl font-bold flex items-center gap-2 serif-font mb-6">
          <ICONS.Admin /> Creator Studio
        </h2>

        <div className="space-y-4">
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">Content Type</label>
            <div className="flex bg-stone-100 p-1 rounded-full w-full">
              <button 
                onClick={() => { setContentType('devotional'); setDevotionalEntry(null); setSundaySchoolEntry(null); }}
                className={`flex-1 py-2 rounded-full transition-all font-bold text-xs uppercase tracking-wider ${contentType === 'devotional' ? 'bg-white shadow-sm text-amber-800' : 'text-stone-400'}`}
              >
                Daily Devotional
              </button>
              <button 
                onClick={() => { setContentType('sunday-school'); setMode('manual'); setDevotionalEntry(null); setSundaySchoolEntry(null); }}
                className={`flex-1 py-2 rounded-full transition-all font-bold text-xs uppercase tracking-wider ${contentType === 'sunday-school' ? 'bg-white shadow-sm text-indigo-800' : 'text-stone-400'}`}
              >
                Sunday School
              </button>
            </div>
          </div>

          {contentType === 'devotional' && (
            <div className="flex flex-col gap-2">
              <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest">Entry Mode</label>
              <div className="flex bg-stone-100 p-1 rounded-full w-fit">
                <button 
                  onClick={() => setMode('ai')}
                  className={`px-4 py-1.5 rounded-full transition-all text-[10px] font-bold uppercase tracking-wider ${mode === 'ai' ? 'bg-white shadow-sm text-amber-800' : 'text-stone-400'}`}
                >
                  AI Structuring
                </button>
                <button 
                  onClick={() => setMode('manual')}
                  className={`px-4 py-1.5 rounded-full transition-all text-[10px] font-bold uppercase tracking-wider ${mode === 'manual' ? 'bg-white shadow-sm text-amber-800' : 'text-stone-400'}`}
                >
                  Manual Entry
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="mt-6">
          <textarea
            className={`w-full h-64 p-5 rounded-2xl border border-stone-200 bg-stone-50 focus:ring-2 outline-none transition-all resize-none text-stone-800 text-sm leading-relaxed ${
              contentType === 'devotional' ? 'focus:ring-amber-500/20 focus:border-amber-500' : 'focus:ring-indigo-500/20 focus:border-indigo-500'
            }`}
            placeholder={`Paste your ${contentType === 'devotional' ? 'devotional text' : 'lesson body'} here...`}
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
          />

          <button
            onClick={handleProcess}
            disabled={loading || (!inputText && mode === 'ai')}
            className={`mt-4 w-full py-4 rounded-2xl font-semibold flex items-center justify-center gap-2 active:scale-[0.98] transition-all disabled:opacity-50 ${
              contentType === 'devotional' ? 'bg-amber-800 text-white hover:bg-amber-700' : 'bg-indigo-800 text-white hover:bg-indigo-700'
            }`}
          >
            {loading ? (
              <span className="animate-spin h-5 w-5 border-2 border-white/30 border-t-white rounded-full" />
            ) : (
              mode === 'ai' ? <ICONS.Sparkles /> : null
            )}
            {mode === 'ai' ? 'Organize with Spirit AI' : 'Prepare for Manual Layout'}
          </button>
        </div>
      </div>

      {/* Devotional Review Panel */}
      {devotionalEntry && contentType === 'devotional' && (
        <div className="bg-amber-50/50 p-6 rounded-3xl border border-amber-100 animate-in fade-in slide-in-from-bottom-4 shadow-xl shadow-amber-900/5">
          <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-amber-800/60 mb-6 flex items-center justify-between">
            Devotional Final Curation
            <button onClick={() => setDevotionalEntry(null)} className="text-stone-400 hover:text-stone-600">Cancel</button>
          </h3>

          <div className="space-y-6">
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Title</label>
              <input 
                className="w-full bg-transparent border-b border-amber-200/50 py-2 text-2xl font-bold serif-font text-stone-800 focus:border-amber-500 outline-none transition-all" 
                value={devotionalEntry.title} 
                onChange={e => setDevotionalEntry({...devotionalEntry, title: e.target.value})}
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Scripture</label>
              <input 
                className="w-full bg-transparent border-b border-amber-200/50 py-2 text-sm italic text-stone-700 focus:border-amber-500 outline-none transition-all" 
                value={devotionalEntry.scripture} 
                onChange={e => setDevotionalEntry({...devotionalEntry, scripture: e.target.value})}
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-amber-800/40 uppercase tracking-wider">Body Content</label>
              <textarea 
                className="w-full bg-white/50 p-4 rounded-xl border border-amber-200/50 text-sm h-48 focus:border-amber-500 outline-none resize-none transition-all" 
                value={devotionalEntry.content} 
                onChange={e => setDevotionalEntry({...devotionalEntry, content: e.target.value})}
              />
            </div>
          </div>

          <button
            onClick={handlePublishDevotional}
            className="w-full mt-8 bg-amber-800 text-white py-4 rounded-2xl font-bold shadow-lg shadow-amber-900/20 hover:bg-amber-700 transition-all"
          >
            Publish to Daily Bread
          </button>
        </div>
      )}

      {/* Sunday School Review Panel */}
      {sundaySchoolEntry && contentType === 'sunday-school' && (
        <div className="bg-indigo-50/50 p-6 rounded-3xl border border-indigo-100 animate-in fade-in slide-in-from-bottom-4 shadow-xl shadow-indigo-900/5">
          <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-800/60 mb-6 flex items-center justify-between">
            Sunday School Lesson Review
            <button onClick={() => setSundaySchoolEntry(null)} className="text-stone-400 hover:text-stone-600">Cancel</button>
          </h3>

          <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-indigo-800/40 uppercase tracking-wider">Lesson Title</label>
                <input 
                  className="w-full bg-transparent border-b border-indigo-200/50 py-2 text-xl font-bold serif-font text-stone-800 focus:border-indigo-500 outline-none transition-all" 
                  value={sundaySchoolEntry.title} 
                  onChange={e => setSundaySchoolEntry({...sundaySchoolEntry, title: e.target.value})}
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-indigo-800/40 uppercase tracking-wider">Topic</label>
                <input 
                  className="w-full bg-transparent border-b border-indigo-200/50 py-2 text-sm text-stone-700 focus:border-indigo-500 outline-none transition-all" 
                  value={sundaySchoolEntry.topic} 
                  onChange={e => setSundaySchoolEntry({...sundaySchoolEntry, topic: e.target.value})}
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-indigo-800/40 uppercase tracking-wider">Memory Verse</label>
              <textarea 
                className="w-full bg-white/50 p-3 rounded-xl border border-indigo-200/50 text-sm italic h-20 focus:border-indigo-500 outline-none transition-all" 
                value={sundaySchoolEntry.memoryVerse} 
                onChange={e => setSundaySchoolEntry({...sundaySchoolEntry, memoryVerse: e.target.value})}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-indigo-800/40 uppercase tracking-wider">Lesson Content</label>
              <textarea 
                className="w-full bg-white/50 p-4 rounded-xl border border-indigo-200/50 text-sm h-64 focus:border-indigo-500 outline-none transition-all" 
                value={sundaySchoolEntry.content} 
                onChange={e => setSundaySchoolEntry({...sundaySchoolEntry, content: e.target.value})}
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-indigo-800/40 uppercase tracking-wider">Discussion Questions (one per line)</label>
              <textarea 
                className="w-full bg-white/50 p-3 rounded-xl border border-indigo-200/50 text-xs h-32 focus:border-indigo-500 outline-none transition-all" 
                value={sundaySchoolEntry.discussionQuestions?.join('\n')} 
                onChange={e => setSundaySchoolEntry({...sundaySchoolEntry, discussionQuestions: e.target.value.split('\n')})}
              />
            </div>
          </div>

          <button
            onClick={handlePublishSundaySchool}
            className="w-full mt-8 bg-indigo-800 text-white py-4 rounded-2xl font-bold shadow-lg shadow-indigo-900/20 hover:bg-indigo-700 transition-all"
          >
            Publish to Classroom
          </button>
        </div>
      )}
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link, useParams } from 'react-router-dom';
import { DevotionalEntry, SundaySchoolLesson, UserPreferences, ThemeMode } from './types';
import { storage } from './services/storageService';
import { ADMIN_SECRET_KEY, ICONS } from './constants';
import Layout from './components/Layout';
import DevotionalCard from './components/DevotionalCard';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [sundayLessons, setSundayLessons] = useState<SundaySchoolLesson[]>([]);
  const [bookmarks, setBookmarks] = useState<string[]>(storage.getBookmarks());
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());
  const [notificationStatus, setNotificationStatus] = useState<NotificationPermission>(
    typeof Notification !== 'undefined' ? Notification.permission : 'default'
  );

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  }, []);

  useEffect(() => {
    const handleStorage = () => {
      setBookmarks(storage.getBookmarks());
    };
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, []);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const handleNotificationToggle = async () => {
    if (typeof Notification === 'undefined') {
      alert("This browser does not support notifications.");
      return;
    }
    if (!prefs.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      setNotificationStatus(permission);
      if (permission === 'granted') {
        updatePrefs({ notificationsEnabled: true });
      }
    } else {
      updatePrefs({ notificationsEnabled: false });
    }
  };

  const handleAdminAuth = () => {
    if (isAdmin) {
      if (window.confirm("Do you want to sign out of Admin Mode?")) {
        setIsAdmin(false);
        storage.setAdminMode(false);
      }
      return;
    }
    const key = window.prompt("Enter the Master Access Key to enable Admin Mode:");
    if (key === ADMIN_SECRET_KEY) {
      setIsAdmin(true);
      storage.setAdminMode(true);
      alert("Access Granted. Creator tools enabled.");
    } else if (key !== null) {
      alert("Invalid Access Key.");
    }
  };

  const refreshData = () => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  };

  const bookmarkedDevotionals = devotionals.filter(d => bookmarks.includes(d.id));

  return (
    <Router>
      <Layout theme={prefs.theme} isAdmin={isAdmin}>
        <Routes>
          <Route path="/" element={
            devotionals.length > 0 ? (
              <DevotionalCard entry={devotionals[0]} theme={prefs.theme} fontSize={prefs.fontSize} />
            ) : (
              <div className="flex flex-col items-center justify-center h-96 text-stone-400">
                <p>Waiting for the morning meal...</p>
              </div>
            )
          } />

          <Route path="/archive" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">Spiritual Library</h2>
              {devotionals.map((entry) => (
                <Link 
                  key={entry.id} 
                  to={`/devotional/${entry.id}`}
                  className={`block p-4 rounded-2xl border transition-all hover:translate-x-1 ${
                    prefs.theme === 'dark' ? 'border-stone-800 bg-stone-800/30' : 'border-stone-100 bg-white'
                  }`}
                >
                  <span className="text-[10px] uppercase tracking-widest text-amber-700 font-bold">{new Date(entry.date).toLocaleDateString()}</span>
                  <h3 className="font-semibold text-lg serif-font">{entry.title}</h3>
                  <p className="text-sm text-stone-500 line-clamp-1">{entry.scripture}</p>
                </Link>
              ))}
            </div>
          } />

          <Route path="/lessons" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">Sunday School</h2>
              {sundayLessons.length === 0 ? (
                <p className="text-stone-400 italic">No lessons available yet.</p>
              ) : (
                sundayLessons.map((lesson) => (
                  <Link 
                    key={lesson.id} 
                    to={`/lesson/${lesson.id}`}
                    className={`block p-5 rounded-2xl border transition-all hover:translate-x-1 border-indigo-100 bg-white shadow-sm`}
                  >
                    <div className="flex justify-between items-center mb-1">
                      <span className="text-[10px] uppercase tracking-widest text-indigo-700 font-bold">{lesson.topic}</span>
                      <span className="text-[10px] text-stone-400">{new Date(lesson.date).toLocaleDateString()}</span>
                    </div>
                    <h3 className="font-semibold text-lg serif-font text-indigo-900">{lesson.title}</h3>
                    <p className="text-sm text-stone-500 line-clamp-1 italic">Memory Verse: {lesson.memoryVerse.split('-')[0]}</p>
                  </Link>
                ))
              )}
            </div>
          } />

          <Route path="/lesson/:id" element={<SundaySchoolDetail lessons={sundayLessons} theme={prefs.theme} fontSize={prefs.fontSize} />} />

          <Route path="/bookmarks" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">My Sanctuary</h2>
              {bookmarkedDevotionals.length === 0 ? (
                <div className="text-center py-20 text-stone-400">Your sanctuary is quiet. Save devotionals to find them here.</div>
              ) : (
                bookmarkedDevotionals.map((entry) => (
                  <Link key={entry.id} to={`/devotional/${entry.id}`} className="block p-4 rounded-2xl border border-amber-100 bg-white shadow-sm">
                    <h3 className="font-semibold text-lg serif-font">{entry.title}</h3>
                  </Link>
                ))
              )}
            </div>
          } />

          <Route path="/devotional/:id" element={<DevotionalDetail devotionals={devotionals} theme={prefs.theme} fontSize={prefs.fontSize} />} />

          <Route path="/admin" element={isAdmin ? <AdminPanel onEntryAdded={refreshData} /> : <div className="p-10 text-center">Access Denied</div>} />

          <Route path="/settings" element={
            <div className="pt-6 space-y-8">
              <h2 className="text-2xl font-bold serif-font">Settings</h2>
              <section className="space-y-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Theme</h3>
                <div className="grid grid-cols-3 gap-3">
                  {(['light', 'sepia', 'dark'] as const).map(mode => (
                    <button key={mode} onClick={() => updatePrefs({ theme: mode })} className={`py-3 rounded-xl border-2 transition-all capitalize ${prefs.theme === mode ? 'border-amber-600 bg-amber-50' : 'border-stone-200'}`}>
                      {mode}
                    </button>
                  ))}
                </div>
              </section>
              <section className="space-y-4">
                 <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Notifications</h3>
                 <button onClick={handleNotificationToggle} className="w-full p-4 rounded-xl border border-stone-200 text-left flex justify-between">
                    <span>Daily Reminders</span>
                    <span className={prefs.notificationsEnabled ? 'text-amber-600 font-bold' : 'text-stone-400'}>{prefs.notificationsEnabled ? 'ON' : 'OFF'}</span>
                 </button>
              </section>
              <button onClick={handleAdminAuth} className="w-full py-4 rounded-xl border-2 border-dashed border-stone-200 text-stone-400 hover:border-amber-300 hover:text-amber-800 transition-all">
                {isAdmin ? 'Sign out of Admin' : 'Admin Login'}
              </button>
            </div>
          } />
        </Routes>
      </Layout>
    </Router>
  );
};

const DevotionalDetail: React.FC<{ devotionals: DevotionalEntry[], theme: ThemeMode, fontSize: string }> = ({ devotionals, theme, fontSize }) => {
  const { id } = useParams();
  const entry = devotionals.find(d => d.id === id);
  if (!entry) return <div className="p-8 text-center">Not found</div>;
  return <DevotionalCard entry={entry} theme={theme} fontSize={fontSize} />;
};

const SundaySchoolDetail: React.FC<{ lessons: SundaySchoolLesson[], theme: ThemeMode, fontSize: string }> = ({ lessons, theme, fontSize }) => {
  const { id } = useParams();
  const lesson = lessons.find(l => l.id === id);
  if (!lesson) return <div className="p-8 text-center">Lesson not found</div>;

  const fontSizeClass = { sm: 'text-sm', base: 'text-base', lg: 'text-lg', xl: 'text-xl' }[fontSize as any] || 'text-base';

  return (
    <div className="py-8 animate-in fade-in duration-500">
      <div className="mb-6">
        <span className="text-xs font-bold uppercase tracking-[0.2em] text-indigo-700 block mb-2">{lesson.topic}</span>
        <h2 className={`text-3xl md:text-4xl font-bold leading-tight serif-font ${theme === 'dark' ? 'text-white' : 'text-indigo-950'}`}>{lesson.title}</h2>
        <p className="text-xs text-stone-400 mt-2">{new Date(lesson.date).toLocaleDateString()}</p>
      </div>

      <div className={`p-6 rounded-2xl border-l-4 border-indigo-600 mb-8 bg-indigo-50/50 italic ${theme === 'dark' ? 'text-indigo-200' : 'text-indigo-900'}`}>
        <p className="font-bold mb-1 uppercase text-[10px] tracking-widest opacity-60">Memory Verse</p>
        <p className="text-lg serif-font">"{lesson.memoryVerse}"</p>
      </div>

      <article className={`serif-font leading-relaxed ${fontSizeClass} mb-12 ${theme === 'dark' ? 'text-stone-300' : 'text-stone-700'}`}>
        {lesson.content.split('\n').map((p, i) => <p key={i} className="mb-4">{p}</p>)}
      </article>

      {lesson.discussionQuestions && lesson.discussionQuestions.length > 0 && (
        <section className={`p-8 rounded-3xl ${theme === 'dark' ? 'bg-stone-800' : 'bg-indigo-50/30 border border-indigo-100'}`}>
          <h3 className="text-lg font-bold mb-6 text-indigo-800 serif-font">Discussion Questions</h3>
          <ul className="space-y-4">
            {lesson.discussionQuestions.map((q, i) => (
              <li key={i} className="flex gap-4 items-start">
                <span className="flex-shrink-0 w-6 h-6 rounded-full bg-indigo-200 text-indigo-800 flex items-center justify-center font-bold text-xs">{i + 1}</span>
                <p className="text-sm leading-relaxed">{q}</p>
              </li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
};

export default App;

