// Initialize lazily and ensure fresh instances for reliability
const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.error("CRITICAL: Gemini API Key is missing from environment.");
    throw new Error("API_KEY_MISSING");
  }
  return new GoogleGenAI({ apiKey });
};

export const extractDevotionalStructure = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{
        parts: [{
          text: `You are a professional content editor for a Christian devotional app. 
          Analyze the raw text provided and extract it into a structured JSON format. 

          CRITICAL RULES:
          1. The 'content' field MUST be the verbatim, untouched main body of the text. Do not summarize or rewrite it.
          2. The 'scripture' field should contain the Bible reference and/or the full verse if included.
          3. If no prayer is found, write a short, heartfelt 2-sentence prayer based on the theme.

          Input Text:
          "${text}"`
        }]
      }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "The title of the devotional" },
            scripture: { type: Type.STRING, description: "The Bible verse reference" },
            content: { type: Type.STRING, description: "Verbatim main body text" },
            prayer: { type: Type.STRING, description: "A concluding prayer" },
            meditation: { type: Type.STRING, description: "One-sentence takeaway" },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "scripture", "content", "prayer", "meditation", "tags"]
        }
      }
    });

    const output = response.text?.trim();
    if (!output) throw new Error("Empty response from AI");

    return JSON.parse(output);
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    return null;
  }
};

