export const generateDevotionalAudio = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ 
        parts: [{ 
          text: `Please read this devotional aloud with a calm, warm, and reverent tone. Pace the reading for reflection: ${text}` 
