      <article className={`serif-font leading-relaxed ${fontSizeClass} mb-12 ${theme === 'dark' ? 'text-stone-300' : 'text-stone-700'}`}>
        {lesson.content.split('\n').map((p, i) => <p key={i} className="mb-4">{p}</p>)}
