import { DevotionalEntry, SundaySchoolLesson, UserPreferences } from '../types';
import { INITIAL_DEVOTIONALS, INITIAL_SUNDAY_SCHOOL } from '../constants';

const STORAGE_KEYS = {
  DEVOTIONALS: 'spirit_meal_devotionals',
  SUNDAY_SCHOOL: 'spirit_meal_sunday_school',
  PREFERENCES: 'spirit_meal_prefs',
  ADMIN_MODE: 'spirit_meal_admin',
  BOOKMARKS: 'spirit_meal_bookmarks',
  NOTES: 'spirit_meal_notes'
};

export const storage = {
  getDevotionals: (): DevotionalEntry[] => {
    const data = localStorage.getItem(STORAGE_KEYS.DEVOTIONALS);
    return data ? JSON.parse(data) : INITIAL_DEVOTIONALS;
  },
  saveDevotionals: (devotionals: DevotionalEntry[]) => {
    localStorage.setItem(STORAGE_KEYS.DEVOTIONALS, JSON.stringify(devotionals));
  },
  getSundaySchool: (): SundaySchoolLesson[] => {
    const data = localStorage.getItem(STORAGE_KEYS.SUNDAY_SCHOOL);
    return data ? JSON.parse(data) : INITIAL_SUNDAY_SCHOOL;
  },
  saveSundaySchool: (lessons: SundaySchoolLesson[]) => {
    localStorage.setItem(STORAGE_KEYS.SUNDAY_SCHOOL, JSON.stringify(lessons));
  },
  getPreferences: (): UserPreferences => {
    const data = localStorage.getItem(STORAGE_KEYS.PREFERENCES);
    return data ? JSON.parse(data) : {
      theme: 'light',
      notificationsEnabled: false,
      notificationTime: '07:00',
      fontSize: 'base'
    };
  },
  savePreferences: (prefs: UserPreferences) => {
    localStorage.setItem(STORAGE_KEYS.PREFERENCES, JSON.stringify(prefs));
  },
  getAdminMode: (): boolean => {
    return localStorage.getItem(STORAGE_KEYS.ADMIN_MODE) === 'true';
  },
  setAdminMode: (active: boolean) => {
    localStorage.setItem(STORAGE_KEYS.ADMIN_MODE, active ? 'true' : 'false');
  },
  getBookmarks: (): string[] => {
    const data = localStorage.getItem(STORAGE_KEYS.BOOKMARKS);
    return data ? JSON.parse(data) : [];
  },
  saveBookmarks: (ids: string[]) => {
    localStorage.setItem(STORAGE_KEYS.BOOKMARKS, JSON.stringify(ids));
  },
  toggleBookmark: (id: string): boolean => {
    const bookmarks = storage.getBookmarks();
    const index = bookmarks.indexOf(id);
    let isAdded = false;

    if (index === -1) {
      bookmarks.push(id);
      isAdded = true;
    } else {
      bookmarks.splice(index, 1);
      isAdded = false;
    }

    storage.saveBookmarks(bookmarks);
    return isAdded;
  },
  getNotes: (): Record<string, string> => {
    const data = localStorage.getItem(STORAGE_KEYS.NOTES);
    return data ? JSON.parse(data) : {};
  },
  getNote: (id: string): string => {
    return storage.getNotes()[id] || '';
  },
  saveNote: (id: string, note: string) => {
    const notes = storage.getNotes();
    if (!note.trim()) {
      delete notes[id];
    } else {
      notes[id] = note;
    }
    localStorage.setItem(STORAGE_KEYS.NOTES, JSON.stringify(notes));
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { DevotionalEntry, ThemeMode } from '../types';
import { getDailyReflections } from '../services/geminiService';
import { storage } from '../services/storageService';
import { ICONS } from '../constants';

interface Props {
  entry: DevotionalEntry;
  theme: ThemeMode;
  fontSize: string;
}

const DevotionalCard: React.FC<Props> = ({ entry, theme, fontSize }) => {
  const [reflections, setReflections] = useState<string[]>([]);
  const [loadingReflections, setLoadingReflections] = useState(false);
  const [isBookmarked, setIsBookmarked] = useState(false);
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);
  const [userNote, setUserNote] = useState('');
  const [isSavingNote, setIsSavingNote] = useState(false);
  const noteTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    const bookmarks = storage.getBookmarks();
    setIsBookmarked(bookmarks.includes(entry.id));
    setUserNote(storage.getNote(entry.id));

    const fetchReflections = async () => {
      setLoadingReflections(true);
      const res = await getDailyReflections(entry.content);
      setReflections(res);
      setLoadingReflections(false);
    };
    fetchReflections();
  }, [entry.id, entry.content]);

  const toggleBookmark = () => {
    const newState = storage.toggleBookmark(entry.id);
    setIsBookmarked(newState);
  };

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newNote = e.target.value;
    setUserNote(newNote);

    // Auto-save logic with debounce
    if (noteTimeoutRef.current) window.clearTimeout(noteTimeoutRef.current);
    setIsSavingNote(true);

    noteTimeoutRef.current = window.setTimeout(() => {
      storage.saveNote(entry.id, newNote);
      setIsSavingNote(false);
    }, 1000);
  };

  const handleShare = async () => {
    const shareData = {
      title: `Spirit Meal: ${entry.title}`,
      text: `${entry.title}\n\n"${entry.scripture}"\n\nRead more at Spirit Meal.`,
      url: window.location.href,
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.error('Error sharing:', err);
      }
    } else {
      try {
        await navigator.clipboard.writeText(`${shareData.text}\n${shareData.url}`);
        setShowCopyFeedback(true);
        setTimeout(() => setShowCopyFeedback(false), 2000);
      } catch (err) {
        console.error('Failed to copy text: ', err);
      }
    }
  };

  const fontSizeClass = {
    sm: 'text-sm',
    base: 'text-base',
    lg: 'text-lg',
    xl: 'text-xl'
  }[fontSize as 'sm' | 'base' | 'lg' | 'xl'] || 'text-base';

  return (
    <div className="py-8 animate-in fade-in duration-700 relative">
      {/* Hero Image Section */}
      {entry.imageUrl && (
        <div className="mb-8 rounded-3xl overflow-hidden shadow-xl shadow-stone-200/50 border border-stone-100 aspect-video group">
          <img 
            src={entry.imageUrl} 
            alt={entry.title} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
          />
        </div>
      )}

      <div className="flex justify-between items-start mb-6">
        <div className="flex-1">
          <span className="text-xs font-bold uppercase tracking-[0.2em] text-amber-800/60 block mb-2">
            {new Date(entry.date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
          </span>
          <h2 className={`text-3xl md:text-4xl font-bold leading-tight serif-font pr-8 ${theme === 'dark' ? 'text-white' : 'text-stone-900'}`}>
            {entry.title}
          </h2>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={handleShare}
            className={`p-3 rounded-full transition-all duration-300 active:scale-90 relative ${
              theme === 'dark' ? 'text-stone-400 hover:text-stone-200 bg-stone-800' : 'text-stone-400 hover:text-stone-600 bg-stone-100'
            }`}
            title="Share Devotional"
          >
            <ICONS.Share />
            {showCopyFeedback && (
              <span className="absolute -top-10 left-1/2 -translate-x-1/2 px-3 py-1 bg-black text-white text-[10px] rounded-md animate-in fade-in slide-in-from-bottom-2 whitespace-nowrap font-bold uppercase tracking-widest">
                Copied!
              </span>
            )}
          </button>
          <button 
            onClick={toggleBookmark}
            className={`p-3 rounded-full transition-all duration-300 active:scale-90 ${
              isBookmarked 
                ? 'bg-amber-100 text-amber-600 shadow-sm' 
                : theme === 'dark' ? 'text-stone-400 hover:text-stone-200 bg-stone-800' : 'text-stone-400 hover:text-stone-600 bg-stone-100'
            }`}
            title={isBookmarked ? "Remove from Sanctuary" : "Save to Sanctuary"}
          >
            {isBookmarked ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                <path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" />
              </svg>
            ) : (
              <ICONS.Bookmark />
            )}
          </button>
        </div>
      </div>

      <div className={`p-6 rounded-2xl border-l-4 border-amber-600 mb-8 italic ${
        theme === 'dark' ? 'bg-stone-800 text-stone-300' : 'bg-amber-50 text-amber-900'
      }`}>
        <p className="font-medium">{entry.scripture}</p>
      </div>

      <article className={`serif-font leading-relaxed ${fontSizeClass} mb-12 ${
        theme === 'dark' ? 'text-stone-300' : 'text-stone-700'
      }`}>
        {entry.content.split('\n').map((para, i) => (
          <p key={i} className="mb-4">{para}</p>
        ))}
      </article>

      {entry.prayer && (
        <div className="p-8 rounded-3xl border border-amber-100 bg-white shadow-sm text-center mb-12">
          <h3 className="text-xs font-bold uppercase tracking-widest text-amber-700 mb-4">A Moment of Prayer</h3>
          <p className="text-lg italic serif-font text-stone-500">"{entry.prayer}"</p>
        </div>
      )}

      {/* User Notes Section - Appears only when bookmarked */}
      {isBookmarked && (
        <section className={`mb-12 p-8 rounded-3xl border-2 border-dashed ${
          theme === 'dark' ? 'border-stone-800 bg-stone-900' : 'border-amber-100 bg-amber-50/30'
        } animate-in slide-in-from-bottom-4 duration-500`}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <div className="text-amber-700"><ICONS.Pencil /></div>
              <h3 className={`text-lg font-semibold serif-font ${theme === 'dark' ? 'text-amber-200' : 'text-amber-900'}`}>My Sanctuary Notes</h3>
            </div>
            {isSavingNote && (
              <span className="text-[10px] font-bold uppercase tracking-widest text-stone-400 animate-pulse">Saving...</span>
            )}
          </div>
          <textarea
            value={userNote}
            onChange={handleNoteChange}
            placeholder="Record your personal reflections, revelations, or prayers related to this meal..."
            className={`w-full h-40 p-4 rounded-xl resize-none outline-none transition-all ${
              theme === 'dark' 
                ? 'bg-stone-800 border-stone-700 text-stone-300 focus:border-amber-900/50' 
                : 'bg-white border-amber-200 text-stone-700 focus:border-amber-400 focus:ring-4 focus:ring-amber-500/5'
            } border text-sm leading-relaxed serif-font`}
          />
          <p className="text-[10px] mt-2 text-stone-400 italic">Notes are saved automatically and kept on this device.</p>
        </section>
      )}

      <section className={`p-8 rounded-3xl ${theme === 'dark' ? 'bg-stone-800/50' : 'bg-stone-100'}`}>
        <div className="flex items-center gap-2 mb-6">
          <ICONS.Sparkles />
          <h3 className="text-lg font-semibold">
            Spirit Reflections
          </h3>
        </div>
        {loadingReflections ? (
          <div className="space-y-4">
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-full"></div>
            <div className="h-4 bg-stone-200 animate-pulse rounded-full w-3/4"></div>
          </div>
        ) : (
          <ul className="space-y-6">
            {reflections.map((q, i) => (
              <li key={i} className="flex gap-4">
                <span className="flex-shrink-0 w-8 h-8 rounded-full bg-amber-200 text-amber-800 flex items-center justify-center font-bold text-sm">
                  {i + 1}
                </span>
                <p className="text-sm leading-relaxed">{q}</p>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
};

export default DevotionalCard;

import { DevotionalEntry, SundaySchoolLesson, UserPreferences } from '../types';
import { INITIAL_DEVOTIONALS, INITIAL_SUNDAY_SCHOOL } from '../constants';

const STORAGE_KEYS = {
  DEVOTIONALS: 'spirit_meal_devotionals',
  SUNDAY_SCHOOL: 'spirit_meal_sunday_school',
  PREFERENCES: 'spirit_meal_prefs',
  ADMIN_MODE: 'spirit_meal_admin',
  BOOKMARKS: 'spirit_meal_bookmarks',
  NOTES: 'spirit_meal_notes'
};

// Custom event for same-window sync
const SYNC_EVENT = 'spirit_meal_sync';

const notifySync = () => {
  window.dispatchEvent(new CustomEvent(SYNC_EVENT));
};

export const storage = {
  SYNC_EVENT,
  getDevotionals: (): DevotionalEntry[] => {
    const data = localStorage.getItem(STORAGE_KEYS.DEVOTIONALS);
    return data ? JSON.parse(data) : INITIAL_DEVOTIONALS;
  },
  saveDevotionals: (devotionals: DevotionalEntry[]) => {
    localStorage.setItem(STORAGE_KEYS.DEVOTIONALS, JSON.stringify(devotionals));
    notifySync();
  },
  getSundaySchool: (): SundaySchoolLesson[] => {
    const data = localStorage.getItem(STORAGE_KEYS.SUNDAY_SCHOOL);
    return data ? JSON.parse(data) : INITIAL_SUNDAY_SCHOOL;
  },
  saveSundaySchool: (lessons: SundaySchoolLesson[]) => {
    localStorage.setItem(STORAGE_KEYS.SUNDAY_SCHOOL, JSON.stringify(lessons));
    notifySync();
  },
  getPreferences: (): UserPreferences => {
    const data = localStorage.getItem(STORAGE_KEYS.PREFERENCES);
    return data ? JSON.parse(data) : {
      theme: 'light',
      notificationsEnabled: false,
      notificationTime: '07:00',
      fontSize: 'base'
    };
  },
  savePreferences: (prefs: UserPreferences) => {
    localStorage.setItem(STORAGE_KEYS.PREFERENCES, JSON.stringify(prefs));
    notifySync();
  },
  getAdminMode: (): boolean => {
    return localStorage.getItem(STORAGE_KEYS.ADMIN_MODE) === 'true';
  },
  setAdminMode: (active: boolean) => {
    localStorage.setItem(STORAGE_KEYS.ADMIN_MODE, active ? 'true' : 'false');
    notifySync();
  },
  getBookmarks: (): string[] => {
    const data = localStorage.getItem(STORAGE_KEYS.BOOKMARKS);
    return data ? JSON.parse(data) : [];
  },
  saveBookmarks: (ids: string[]) => {
    localStorage.setItem(STORAGE_KEYS.BOOKMARKS, JSON.stringify(ids));
    notifySync();
  },
  toggleBookmark: (id: string): boolean => {
    const bookmarks = storage.getBookmarks();
    const index = bookmarks.indexOf(id);
    let isAdded = false;

    if (index === -1) {
      bookmarks.push(id);
      isAdded = true;
    } else {
      bookmarks.splice(index, 1);
      isAdded = false;
    }

    storage.saveBookmarks(bookmarks);
    return isAdded;
  },
  getNotes: (): Record<string, string> => {
    const data = localStorage.getItem(STORAGE_KEYS.NOTES);
    return data ? JSON.parse(data) : {};
  },
  getNote: (id: string): string => {
    return storage.getNotes()[id] || '';
  },
  saveNote: (id: string, note: string) => {
    const notes = storage.getNotes();
    if (!note.trim()) {
      delete notes[id];
    } else {
      notes[id] = note;
    }
    localStorage.setItem(STORAGE_KEYS.NOTES, JSON.stringify(notes));
    notifySync();
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Link, useParams } from 'react-router-dom';
import { DevotionalEntry, SundaySchoolLesson, UserPreferences, ThemeMode } from './types';
import { storage } from './services/storageService';
import { ADMIN_SECRET_KEY, ICONS } from './constants';
import Layout from './components/Layout';
import DevotionalCard from './components/DevotionalCard';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [sundayLessons, setSundayLessons] = useState<SundaySchoolLesson[]>([]);
  const [bookmarks, setBookmarks] = useState<string[]>(storage.getBookmarks());
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());
  const [notificationStatus, setNotificationStatus] = useState<NotificationPermission>(
    typeof Notification !== 'undefined' ? Notification.permission : 'default'
  );

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  }, []);

  useEffect(() => {
    const handleSync = () => {
      setBookmarks(storage.getBookmarks());
      setPrefs(storage.getPreferences());
      setIsAdmin(storage.getAdminMode());
    };

    // Standard cross-tab sync
    window.addEventListener('storage', handleSync);
    // Same-window custom sync
    window.addEventListener(storage.SYNC_EVENT, handleSync);

    return () => {
      window.removeEventListener('storage', handleSync);
      window.removeEventListener(storage.SYNC_EVENT, handleSync);
    };
  }, []);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const handleNotificationToggle = async () => {
    if (typeof Notification === 'undefined') {
      alert("This browser does not support notifications.");
      return;
    }

    if (!prefs.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      setNotificationStatus(permission);
      if (permission === 'granted') {
        updatePrefs({ notificationsEnabled: true });
      } else {
        alert("Please enable notifications in your browser settings to receive reminders.");
      }
    } else {
      updatePrefs({ notificationsEnabled: false });
    }
  };

  const handleAdminAuth = () => {
    if (isAdmin) {
      if (window.confirm("Do you want to sign out of Admin Mode?")) {
        setIsAdmin(false);
        storage.setAdminMode(false);
      }
      return;
    }
    const key = window.prompt("Enter the Master Access Key to enable Admin Mode:");
    if (key === ADMIN_SECRET_KEY) {
      setIsAdmin(true);
      storage.setAdminMode(true);
      alert("Access Granted. Creator tools enabled.");
    } else if (key !== null) {
      alert("Invalid Access Key.");
    }
  };

  const refreshData = () => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  };

  const bookmarkedDevotionals = devotionals.filter(d => bookmarks.includes(d.id));

  return (
    <Router>
      <Layout theme={prefs.theme} isAdmin={isAdmin}>
        <Routes>
          <Route path="/" element={
            devotionals.length > 0 ? (
              <DevotionalCard entry={devotionals[0]} theme={prefs.theme} fontSize={prefs.fontSize} />
            ) : (
              <div className="flex flex-col items-center justify-center h-96 text-stone-400">
                <p>Waiting for the morning meal...</p>
              </div>
            )
          } />

          <Route path="/archive" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">Spiritual Library</h2>
              {devotionals.map((entry) => (
                <Link 
                  key={entry.id} 
                  to={`/devotional/${entry.id}`}
                  className={`block p-4 rounded-2xl border transition-all hover:translate-x-1 ${
                    prefs.theme === 'dark' ? 'border-stone-800 bg-stone-800/30' : 'border-stone-100 bg-white shadow-sm'
                  }`}
                >
                  <span className="text-[10px] uppercase tracking-widest text-amber-700 font-bold">{new Date(entry.date).toLocaleDateString()}</span>
                  <h3 className="font-semibold text-lg serif-font">{entry.title}</h3>
                  <p className="text-sm text-stone-500 line-clamp-1">{entry.scripture}</p>
                </Link>
              ))}
            </div>
          } />

          <Route path="/lessons" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">Sunday School</h2>
              {sundayLessons.length === 0 ? (
                <p className="text-stone-400 italic">No lessons available yet.</p>
              ) : (
                sundayLessons.map((lesson) => (
                  <Link 
                    key={lesson.id} 
                    to={`/lesson/${lesson.id}`}
                    className={`block p-5 rounded-2xl border transition-all hover:translate-x-1 border-indigo-100 bg-white shadow-sm`}
                  >
                    <div className="flex justify-between items-center mb-1">
                      <span className="text-[10px] uppercase tracking-widest text-indigo-700 font-bold">{lesson.topic}</span>
                      <span className="text-[10px] text-stone-400">{new Date(lesson.date).toLocaleDateString()}</span>
                    </div>
                    <h3 className="font-semibold text-lg serif-font text-indigo-900">{lesson.title}</h3>
                    <p className="text-sm text-stone-500 line-clamp-1 italic">Memory Verse: {lesson.memoryVerse.split('-')[0]}</p>
                  </Link>
                ))
              )}
            </div>
          } />

          <Route path="/lesson/:id" element={<SundaySchoolDetail lessons={sundayLessons} theme={prefs.theme} fontSize={prefs.fontSize} />} />

          <Route path="/bookmarks" element={
            <div className="pt-6 space-y-4">
              <h2 className="text-2xl font-bold serif-font mb-6">My Sanctuary</h2>
              {bookmarkedDevotionals.length === 0 ? (
                <div className="text-center py-20 text-stone-400">Your sanctuary is quiet. Save devotionals to find them here.</div>
              ) : (
                bookmarkedDevotionals.map((entry) => (
                  <Link key={entry.id} to={`/devotional/${entry.id}`} className="block p-4 rounded-2xl border border-amber-100 bg-white shadow-sm">
                    <h3 className="font-semibold text-lg serif-font">{entry.title}</h3>
                  </Link>
                ))
              )}
            </div>
          } />

          <Route path="/devotional/:id" element={<DevotionalDetail devotionals={devotionals} theme={prefs.theme} fontSize={prefs.fontSize} />} />

          <Route path="/admin" element={isAdmin ? <AdminPanel onEntryAdded={refreshData} /> : <div className="p-10 text-center">Access Denied</div>} />

          <Route path="/settings" element={
            <div className="pt-6 space-y-8 pb-20">
              <h2 className="text-2xl font-bold serif-font">Settings</h2>

              <section className="space-y-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Appearance</h3>
                <div className="grid grid-cols-3 gap-3">
                  {(['light', 'sepia', 'dark'] as const).map(mode => (
                    <button 
                      key={mode} 
                      onClick={() => updatePrefs({ theme: mode })} 
                      className={`py-3 rounded-xl border-2 transition-all capitalize text-sm font-medium ${prefs.theme === mode ? 'border-amber-600 bg-amber-50 text-amber-900 shadow-sm' : 'border-stone-200'}`}
                    >
                      {mode}
                    </button>
                  ))}
                </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Typography</h3>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  {[
                    { id: 'sm', label: 'Small' },
                    { id: 'base', label: 'Standard' },
                    { id: 'lg', label: 'Large' },
                    { id: 'xl', label: 'Extra Large' }
                  ].map(size => (
                    <button 
                      key={size.id} 
                      onClick={() => updatePrefs({ fontSize: size.id as any })} 
                      className={`py-3 rounded-xl border-2 transition-all text-sm font-medium ${prefs.fontSize === size.id ? 'border-amber-600 bg-amber-50 text-amber-900 shadow-sm' : 'border-stone-200'}`}
                    >
                      {size.label}
                    </button>
                  ))}
                </div>
              </section>

              <section className="space-y-4">
                 <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Notifications</h3>
                 <div className={`p-5 rounded-2xl border transition-all ${prefs.notificationsEnabled ? 'bg-amber-50 border-amber-100' : 'bg-white border-stone-100'}`}>
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${prefs.notificationsEnabled ? 'bg-amber-600 text-white' : 'bg-stone-100 text-stone-400'}`}>
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path d="M10 2a6 6 0 00-6 6v3.586l-.707.707A1 1 0 004 14h12a1 1 0 00.707-1.707L16 11.586V8a6 6 0 00-6-6zM10 18a3 3 0 01-3-3h6a3 3 0 01-3 3z" />
                          </svg>
                        </div>
                        <div>
                          <p className="font-bold text-sm">Daily Reminders</p>
                          <p className="text-xs text-stone-500">Get nudged to read your meal</p>
                        </div>
                      </div>
                      <button 
                        onClick={handleNotificationToggle}
                        className={`w-12 h-6 rounded-full transition-colors relative ${prefs.notificationsEnabled ? 'bg-amber-600' : 'bg-stone-200'}`}
                      >
                        <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${prefs.notificationsEnabled ? 'left-7' : 'left-1'}`} />
                      </button>
                    </div>

                    {prefs.notificationsEnabled && (
                      <div className="mt-4 pt-4 border-t border-amber-200/50 animate-in fade-in slide-in-from-top-2">
                        <label className="text-[10px] font-bold text-amber-800 uppercase tracking-widest block mb-2">Preferred Reminder Time</label>
                        <input 
                          type="time" 
                          value={prefs.notificationTime}
                          onChange={(e) => updatePrefs({ notificationTime: e.target.value })}
                          className="w-full p-3 rounded-xl border border-amber-200 bg-white text-lg font-bold text-center focus:outline-none focus:ring-2 focus:ring-amber-500/20"
                        />
                        <p className="text-[10px] text-amber-700/60 mt-2 text-center">Reminders will be sent even if the app is closed.</p>
                      </div>
                    )}
                 </div>
              </section>

              <section className="space-y-4">
                <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Offline Access</h3>
                <div className="bg-stone-100 p-4 rounded-2xl flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-stone-200 flex items-center justify-center text-stone-500">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M2 9.5A3.5 3.5 0 005.5 13H9v2.586l-1.293-1.293a1 1 0 00-1.414 1.414l3 3a1 1 0 001.414 0l3-3a1 1 0 00-1.414-1.414L11 15.586V13h2.5a4.5 4.5 0 10-.616-8.958 4.002 4.002 0 10-7.753 1.977A3.5 3.5 0 002 9.5zm9 3.5H9V8a1 1 0 012 0v5z" clipRule="evenodd" />
                    </svg>
                  </div>
                  <p className="text-xs text-stone-600">App automatically works offline once loaded. Your devotionals are stored locally.</p>
                </div>
              </section>

              <button onClick={handleAdminAuth} className="w-full py-4 rounded-xl border-2 border-dashed border-stone-200 text-stone-400 hover:border-amber-300 hover:text-amber-800 transition-all font-bold text-xs uppercase tracking-widest">
                {isAdmin ? 'Sign out of Admin' : 'Admin Login'}
              </button>
            </div>
          } />
        </Routes>
      </Layout>
    </Router>
  );
};

