const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [sundayLessons, setSundayLessons] = useState<SundaySchoolLesson[]>([]);
  const [bookmarks, setBookmarks] = useState<string[]>(storage.getBookmarks());
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());
  const lastReminderRef = useRef<string | null>(null);

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  }, []);

  useEffect(() => {
    const handleSync = () => {
      setBookmarks(storage.getBookmarks());
      setPrefs(storage.getPreferences());
      setIsAdmin(storage.getAdminMode());
    };

    window.addEventListener('storage', handleSync);
    window.addEventListener(storage.SYNC_EVENT, handleSync);

    return () => {
      window.removeEventListener('storage', handleSync);
      window.removeEventListener(storage.SYNC_EVENT, handleSync);
    };
  }, []);

  // LOCAL REMINDER SYSTEM
  // This triggers a browser notification if the current time matches the set time.
  useEffect(() => {
    if (!prefs.notificationsEnabled) return;

    const checkReminders = () => {
      const now = new Date();
      const currentHours = now.getHours().toString().padStart(2, '0');
      const currentMinutes = now.getMinutes().toString().padStart(2, '0');
      const currentTimeStr = `${currentHours}:${currentMinutes}`;

      // Only trigger once per minute
      if (currentTimeStr === prefs.notificationTime && lastReminderRef.current !== currentTimeStr) {
        lastReminderRef.current = currentTimeStr;

        if (Notification.permission === 'granted') {
          new Notification("Spirit Meal", {
            body: "Your daily spiritual meal is ready. Take a moment for reflection.",
            icon: "/icon-192.png" // Fallback icon path
          });
        }
      }
    };

    const intervalId = setInterval(checkReminders, 60000); // Check every minute
    checkReminders(); // Initial check

    return () => clearInterval(intervalId);
  }, [prefs.notificationsEnabled, prefs.notificationTime]);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const handleNotificationToggle = async () => {
    if (typeof Notification === 'undefined') {
      alert("This browser does not support notifications.");
      return;
    }

    if (!prefs.notificationsEnabled) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        updatePrefs({ notificationsEnabled: true });
        alert("Daily reminders enabled! Ensure the app stays open in a tab or is installed as a PWA to receive them.");
      } else {
        alert("Please enable notification permissions in your browser/phone settings to receive reminders.");
      }
    } else {
      updatePrefs({ notificationsEnabled: false });
    }
  };

  const testNotification = () => {
    if (Notification.permission !== 'granted') {
      alert("Please enable notifications first.");
      return;
    }
    new Notification("Spirit Meal Test", {
      body: "This is a test to verify your reminders are working properly!",
      icon: "/icon-192.png"
    });
    alert("Test notification sent! If you didn't see it, check your device's 'Do Not Disturb' or browser notification settings.");
  };

