import { GoogleGenAI, Type } from "@google/genai";
import { storage } from "./storageService";

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");
  return new GoogleGenAI({ apiKey });
};

// Global cache to prevent redundant calls in the same session
const localCache: Record<string, string[]> = {};

export const extractDevotionalStructure = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{
        parts: [{
          text: `Extract this Christian devotional into JSON.
          Verbatim content in 'content'. 
          If no prayer/meditation exists, generate brief ones.

          Text: "${text}"`
        }]
      }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            scripture: { type: Type.STRING },
            content: { type: Type.STRING },
            prayer: { type: Type.STRING },
            meditation: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "scripture", "content", "prayer", "meditation", "tags"]
        }
      }
    });

    const output = response.text?.trim();
    return output ? JSON.parse(output) : null;
  } catch (error) {
    console.error("Extraction Error:", error);
    return null;
  }
};

export const getDailyReflections = async (content: string, id: string): Promise<string[]> => {
  // 1. Check in-memory session cache
  if (localCache[id]) return localCache[id];

  // 2. Check persistent storage cache
  const persistentCache = storage.getReflectionsCache(id);
  if (persistentCache) {
    localCache[id] = persistentCache;
    return persistentCache;
  }

  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{
        parts: [{
          text: `Generate 3 deep, thought-provoking Christian reflection questions for this devotional message: "${content.substring(0, 1000)}"`
        }]
      }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            questions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["questions"]
        }
      }
    });

    const output = response.text?.trim();
    if (!output) throw new Error("Empty response");
    const parsed = JSON.parse(output);
    const questions = parsed.questions || [];

    // Save to both caches
    localCache[id] = questions;
    storage.saveReflectionsToCache(id, questions);

    return questions;
  } catch (error: any) {
    // Check specifically for rate limiting (429)
    const isRateLimited = error?.message?.includes('429') || error?.status === 429;

    if (isRateLimited) {
      console.warn("Gemini Quota Exceeded. Using spiritual fallbacks.");
    } else {
      console.error("Reflections Error:", error);
    }

    const fallbacks = [
      "How does this message challenge your current walk with God?",
      "In what practical way can you apply this truth to your life today?",
      "Who in your life needs to hear this encouragement right now?"
    ];

    return fallbacks;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { DevotionalEntry, ThemeMode } from '../types';
import { getDailyReflections } from '../services/geminiService';
import { storage } from '../services/storageService';
import { ICONS } from '../constants';

interface Props {
  entry: DevotionalEntry;
  theme: ThemeMode;
  fontSize: string;
}

const DevotionalCard: React.FC<Props> = ({ entry, theme, fontSize }) => {
  const [reflections, setReflections] = useState<string[]>([]);
  const [loadingReflections, setLoadingReflections] = useState(false);
  const [isBookmarked, setIsBookmarked] = useState(false);
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);
  const [userNote, setUserNote] = useState('');
  const [isSavingNote, setIsSavingNote] = useState(false);
  const noteTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    const syncState = () => {
      const bookmarks = storage.getBookmarks();
      setIsBookmarked(bookmarks.includes(entry.id));
      setUserNote(storage.getNote(entry.id));
    };

    syncState();

    const fetchReflections = async () => {
      setLoadingReflections(true);
      const res = await getDailyReflections(entry.content, entry.id);
      setReflections(res);
      setLoadingReflections(false);
    };

    fetchReflections();

    window.addEventListener(storage.SYNC_EVENT, syncState);
    window.addEventListener('storage', syncState);

    return () => {
      window.removeEventListener(storage.SYNC_EVENT, syncState);
      window.removeEventListener('storage', syncState);
    };
  }, [entry.id, entry.content]);

  const toggleBookmark = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const newState = storage.toggleBookmark(entry.id);
    setIsBookmarked(newState);
  };

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newNote = e.target.value;
    setUserNote(newNote);

    if (noteTimeoutRef.current) window.clearTimeout(noteTimeoutRef.current);
    setIsSavingNote(true);

    noteTimeoutRef.current = window.setTimeout(() => {
      storage.saveNote(entry.id, newNote);
      setIsSavingNote(false);
    }, 1000);
  };

  const handleShare = async () => {
    const shareData = {
      title: `Spirit Meal: ${entry.title}`,
      text: `${entry.title}\n\n"${entry.scripture}"\n\nRead more at Spirit Meal.`,
      url: window.location.href,
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.error('Error sharing:', err);
      }
    } else {
      try {
        await navigator.clipboard.writeText(`${shareData.text}\n${shareData.url}`);
        setShowCopyFeedback(true);
        setTimeout(() => setShowCopyFeedback(false), 2000);
      } catch (err) {
        console.error('Failed to copy text: ', err);
      }
    }
  };

  const fontSizeClass = {
    sm: 'text-sm',
    base: 'text-base',
    lg: 'text-lg',
    xl: 'text-xl'
  }[fontSize as 'sm' | 'base' | 'lg' | 'xl'] || 'text-base';

  return (
    <div className="py-8 animate-in fade-in duration-700 relative">
      {entry.imageUrl && (
        <div className="mb-8 rounded-3xl overflow-hidden shadow-xl shadow-stone-200/50 border border-stone-100 aspect-video group">
          <img 
            src={entry.imageUrl} 
            alt={entry.title} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
          />
        </div>
      )}

      <div className="flex justify-between items-start mb-6">
        <div className="flex-1">
          <span className="text-xs font-bold uppercase tracking-[0.2em] text-amber-800/60 block mb-2">
            {new Date(entry.date).toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
          </span>
