                    )}
                 </div>
              </section>

              <button onClick={handleAdminAuth} className="w-full py-4 rounded-xl border-2 border-dashed border-stone-200 text-stone-400 font-bold text-xs uppercase tracking-widest">
                {isAdmin ? 'Logout' : 'Admin Access'}
              </button>
            </div>
          } />
        </Routes>
      </Layout>
    </Router>
  );
};

