import { GoogleGenAI, Type } from "@google/genai";
import { storage } from "./storageService.ts";

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");
  return new GoogleGenAI({ apiKey });
};

// Rate limit circuit breaker
let quotaExhaustedUntil = 0;
const QUOTA_BACKOFF_MS = 5 * 60 * 1000; // 5 minutes

export const getDailyReflections = async (content: string, id: string): Promise<string[]> => {
  // 1. Check persistent cache first
  const cached = storage.getReflectionsCache(id);
  if (cached) return cached;

  // 2. Check circuit breaker
  if (Date.now() < quotaExhaustedUntil) {
    console.warn("Circuit Breaker Active: Using spiritual fallbacks due to API quota.");
    return getFallbacks();
  }

  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{
        parts: [{
          text: `Generate 3 thought-provoking Christian reflection questions based on this message: "${content.substring(0, 1000)}"`
        }]
      }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            questions: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["questions"]
        }
      }
    });

    const output = response.text?.trim();
    const questions = output ? JSON.parse(output).questions : getFallbacks();

    storage.saveReflectionsToCache(id, questions);
    return questions;
  } catch (error: any) {
    if (error?.status === 429 || error?.message?.includes('429')) {
      quotaExhaustedUntil = Date.now() + QUOTA_BACKOFF_MS;
    }
    return getFallbacks();
  }
};

const getFallbacks = () => [
  "How can you apply this teaching to your relationships today?",
  "What specific part of this scripture touched your heart the most?",
  "In what area of your life is God calling you to be 'still' right now?"
];

export const extractDevotionalStructure = async (text: string) => {
  try {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{ parts: [{ text: `Extract into JSON: ${text}` }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            scripture: { type: Type.STRING },
            content: { type: Type.STRING },
            prayer: { type: Type.STRING },
            meditation: { type: Type.STRING },
            tags: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    return response.text ? JSON.parse(response.text) : null;
  } catch (error) {
    return null;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Link, useParams } from 'react-router-dom';
import { DevotionalEntry, SundaySchoolLesson, UserPreferences, ThemeMode } from './types.ts';
import { storage } from './services/storageService.ts';
import { ADMIN_SECRET_KEY, ICONS } from './constants.tsx';
import Layout from './components/Layout.tsx';
import DevotionalCard from './components/DevotionalCard.tsx';
import AdminPanel from './components/AdminPanel.tsx';

const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [sundayLessons, setSundayLessons] = useState<SundaySchoolLesson[]>([]);
  const [bookmarks, setBookmarks] = useState<string[]>(storage.getBookmarks());
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());
  const [isStandalone, setIsStandalone] = useState(false);
  const lastReminderRef = useRef<string | null>(null);

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
    setIsStandalone(window.matchMedia('(display-mode: standalone)').matches);
  }, []);

  useEffect(() => {
    const handleSync = () => {
      setBookmarks(storage.getBookmarks());
      setPrefs(storage.getPreferences());
      setIsAdmin(storage.getAdminMode());
    };
    window.addEventListener('storage', handleSync);
    window.addEventListener(storage.SYNC_EVENT, handleSync);
    return () => {
      window.removeEventListener('storage', handleSync);
      window.removeEventListener(storage.SYNC_EVENT, handleSync);
    };
  }, []);

  // Reminder Logic
  useEffect(() => {
    if (!prefs.notificationsEnabled) return;
    const intervalId = setInterval(() => {
      const now = new Date();
      const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      if (time === prefs.notificationTime && lastReminderRef.current !== time) {
        lastReminderRef.current = time;
        if (Notification.permission === 'granted') {
          new Notification("Spirit Meal", { body: "Your daily spiritual meal is ready." });
        }
      }
    }, 15000);
    return () => clearInterval(intervalId);
  }, [prefs.notificationsEnabled, prefs.notificationTime]);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const handleNotificationToggle = async () => {
    if (Notification.permission !== 'granted') {
      const permission = await Notification.requestPermission();
      if (permission !== 'granted') {
        alert("Please allow notifications in your browser settings first.");
        return;
      }
    }
    updatePrefs({ notificationsEnabled: !prefs.notificationsEnabled });
  };

  return (
    <Router>
      <Layout theme={prefs.theme} isAdmin={isAdmin}>
        <Routes>
