import { DevotionalEntry, SundaySchoolLesson, UserPreferences } from '../types';
import { INITIAL_DEVOTIONALS, INITIAL_SUNDAY_SCHOOL } from '../constants';

const STORAGE_KEYS = {
  DEVOTIONALS: 'spirit_meal_devotionals',
  SUNDAY_SCHOOL: 'spirit_meal_sunday_school',
  PREFERENCES: 'spirit_meal_prefs',
  ADMIN_MODE: 'spirit_meal_admin',
  BOOKMARKS: 'spirit_meal_bookmarks',
  NOTES: 'spirit_meal_notes',
  REFLECTIONS_CACHE: 'spirit_meal_reflections'
};

// Custom event for same-window sync
const SYNC_EVENT = 'spirit_meal_sync';

const notifySync = () => {
  window.dispatchEvent(new CustomEvent(SYNC_EVENT));
};

export const storage = {
  SYNC_EVENT,
  getDevotionals: (): DevotionalEntry[] => {
    const data = localStorage.getItem(STORAGE_KEYS.DEVOTIONALS);
    return data ? JSON.parse(data) : INITIAL_DEVOTIONALS;
  },
  saveDevotionals: (devotionals: DevotionalEntry[]) => {
    localStorage.setItem(STORAGE_KEYS.DEVOTIONALS, JSON.stringify(devotionals));
    notifySync();
  },
  deleteDevotional: (id: string) => {
    const items = storage.getDevotionals().filter(i => i.id !== id);
    storage.saveDevotionals(items);
  },
  getSundaySchool: (): SundaySchoolLesson[] => {
    const data = localStorage.getItem(STORAGE_KEYS.SUNDAY_SCHOOL);
    return data ? JSON.parse(data) : INITIAL_SUNDAY_SCHOOL;
  },
  saveSundaySchool: (lessons: SundaySchoolLesson[]) => {
    localStorage.setItem(STORAGE_KEYS.SUNDAY_SCHOOL, JSON.stringify(lessons));
    notifySync();
  },
  deleteSundaySchool: (id: string) => {
    const items = storage.getSundaySchool().filter(i => i.id !== id);
    storage.saveSundaySchool(items);
  },
  getPreferences: (): UserPreferences => {
    const data = localStorage.getItem(STORAGE_KEYS.PREFERENCES);
    return data ? JSON.parse(data) : {
      theme: 'light',
      notificationsEnabled: false,
      notificationTime: '07:00',
      fontSize: 'base'
    };
  },
  savePreferences: (prefs: UserPreferences) => {
    localStorage.setItem(STORAGE_KEYS.PREFERENCES, JSON.stringify(prefs));
    notifySync();
  },
  getAdminMode: (): boolean => {
    return localStorage.getItem(STORAGE_KEYS.ADMIN_MODE) === 'true';
  },
  setAdminMode: (active: boolean) => {
    localStorage.setItem(STORAGE_KEYS.ADMIN_MODE, active ? 'true' : 'false');
    notifySync();
  },
  getBookmarks: (): string[] => {
    const data = localStorage.getItem(STORAGE_KEYS.BOOKMARKS);
    return data ? JSON.parse(data) : [];
  },
  saveBookmarks: (ids: string[]) => {
    localStorage.setItem(STORAGE_KEYS.BOOKMARKS, JSON.stringify(ids));
    notifySync();
  },
  toggleBookmark: (id: string): boolean => {
    const bookmarks = storage.getBookmarks();
    const index = bookmarks.indexOf(id);
    let isAdded = false;

    if (index === -1) {
      bookmarks.push(id);
      isAdded = true;
    } else {
      bookmarks.splice(index, 1);
      isAdded = false;
    }

    storage.saveBookmarks(bookmarks);
    return isAdded;
  },
  getNotes: (): Record<string, string> => {
    const data = localStorage.getItem(STORAGE_KEYS.NOTES);
    return data ? JSON.parse(data) : {};
  },
  getNote: (id: string): string => {
    return storage.getNotes()[id] || '';
  },
  saveNote: (id: string, note: string) => {
    const notes = storage.getNotes();
    if (!note.trim()) {
      delete notes[id];
    } else {
      notes[id] = note;
    }
    localStorage.setItem(STORAGE_KEYS.NOTES, JSON.stringify(notes));
    notifySync();
  },
  getReflectionsCache: (id: string): string[] | null => {
    const data = localStorage.getItem(STORAGE_KEYS.REFLECTIONS_CACHE);
    if (!data) return null;
    const cache = JSON.parse(data);
    return cache[id] || null;
  },
  saveReflectionsToCache: (id: string, reflections: string[]) => {
    const data = localStorage.getItem(STORAGE_KEYS.REFLECTIONS_CACHE);
    const cache = data ? JSON.parse(data) : {};
    cache[id] = reflections;
    localStorage.setItem(STORAGE_KEYS.REFLECTIONS_CACHE, JSON.stringify(cache));
  }
};

import React, { useState, useEffect } from 'react';
import { extractDevotionalStructure } from '../services/geminiService.ts';
import { DevotionalEntry, SundaySchoolLesson } from '../types.ts';
import { storage } from '../services/storageService.ts';
import { ICONS } from '../constants.tsx';

const AdminPanel: React.FC<{ onEntryAdded: () => void }> = ({ onEntryAdded }) => {
  const [activeTab, setActiveTab] = useState<'devotionals' | 'lessons'>('devotionals');
  const [editingItem, setEditingItem] = useState<any | null>(null);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [aiInput, setAiInput] = useState('');

  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>(storage.getDevotionals());
  const [lessons, setLessons] = useState<SundaySchoolLesson[]>(storage.getSundaySchool());

  const handleCreateNew = () => {
    const id = Date.now().toString();
    const date = new Date().toISOString().split('T')[0];

    if (activeTab === 'devotionals') {
      setEditingItem({
        id, date, title: '', scripture: '', content: '', prayer: '', meditation: '', tags: []
      } as DevotionalEntry);
    } else {
      setEditingItem({
        id, date, title: '', topic: '', memoryVerse: '', content: '', discussionQuestions: []
      } as SundaySchoolLesson);
    }
  };

  const handleEdit = (item: any) => {
    setEditingItem({ ...item });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Are you sure you want to remove this entry forever?')) {
      if (activeTab === 'devotionals') {
        storage.deleteDevotional(id);
        setDevotionals(storage.getDevotionals());
      } else {
        storage.deleteSundaySchool(id);
        setLessons(storage.getSundaySchool());
      }
      onEntryAdded();
    }
  };

  const handleSave = () => {
    if (!editingItem.title || !editingItem.content) {
      alert("Please provide at least a title and content.");
      return;
    }

    if (activeTab === 'devotionals') {
      const current = storage.getDevotionals();
      const index = current.findIndex(d => d.id === editingItem.id);
      if (index > -1) {
        current[index] = editingItem;
      } else {
        current.unshift(editingItem);
      }
      storage.saveDevotionals(current);
      setDevotionals(current);
    } else {
      const current = storage.getSundaySchool();
      const index = current.findIndex(l => l.id === editingItem.id);
      if (index > -1) {
        current[index] = editingItem;
      } else {
        current.unshift(editingItem);
      }
      storage.saveSundaySchool(current);
      setLessons(current);
    }

    setEditingItem(null);
    onEntryAdded();
    alert("Saved successfully.");
  };

  const handleAIExtract = async () => {
    if (!aiInput.trim()) return;
    setIsAIProcessing(true);
    try {
      const result = await extractDevotionalStructure(aiInput);
      if (result) {
        setEditingItem({
          ...editingItem,
          ...result,
          id: editingItem.id || Date.now().toString(),
          date: editingItem.date || new Date().toISOString().split('T')[0]
        });
        setAiInput('');
      } else {
        alert("AI couldn't parse that text. Try a clearer sample.");
      }
    } catch (err) {
      console.error(err);
      alert("AI Tool error. Manual entry recommended.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="pt-6 pb-20 animate-in fade-in slide-in-from-bottom-4">
