                  {prefs.notificationsEnabled && (
                    <div className="space-y-6 animate-in fade-in slide-in-from-top-2">
                      <div>
                        <label className="text-[10px] font-bold text-amber-800 uppercase tracking-widest block mb-2">Preferred Time</label>
