            ))}
          </ul>
        </section>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { extractDevotionalStructure } from '../services/geminiService.ts';
import { DevotionalEntry, SundaySchoolLesson } from '../types.ts';
import { storage } from '../services/storageService.ts';
import { ICONS } from '../constants.tsx';

interface AdminPanelProps {
  onEntryAdded: () => void;
  editId?: string | null;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onEntryAdded, editId }) => {
  const [activeTab, setActiveTab] = useState<'devotionals' | 'lessons'>('devotionals');
  const [editingItem, setEditingItem] = useState<any | null>(null);
  const [isAIProcessing, setIsAIProcessing] = useState(false);
  const [aiInput, setAiInput] = useState('');

  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>(storage.getDevotionals());
  const [lessons, setLessons] = useState<SundaySchoolLesson[]>(storage.getSundaySchool());

  // Automatically open the editor if we came from a specific "Edit" link
  useEffect(() => {
    if (editId) {
      const dev = devotionals.find(d => d.id === editId);
      if (dev) {
        setActiveTab('devotionals');
        setEditingItem({ ...dev });
        return;
      }
      const lesson = lessons.find(l => l.id === editId);
      if (lesson) {
        setActiveTab('lessons');
        setEditingItem({ ...lesson });
      }
    }
  }, [editId, devotionals, lessons]);

  const handleCreateNew = () => {
    const id = Date.now().toString();
    const date = new Date().toISOString().split('T')[0];

    if (activeTab === 'devotionals') {
      setEditingItem({
        id, date, title: '', scripture: '', content: '', prayer: '', meditation: '', tags: []
      } as DevotionalEntry);
    } else {
      setEditingItem({
        id, date, title: '', topic: '', memoryVerse: '', content: '', discussionQuestions: []
      } as SundaySchoolLesson);
    }
  };

  const handleEdit = (item: any) => {
    setEditingItem({ ...item });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this entry forever? This cannot be undone.')) {
      if (activeTab === 'devotionals') {
        storage.deleteDevotional(id);
        setDevotionals(storage.getDevotionals());
      } else {
        storage.deleteSundaySchool(id);
        setLessons(storage.getSundaySchool());
      }
      onEntryAdded();
    }
  };

  const handleSave = () => {
    if (!editingItem.title?.trim() || !editingItem.content?.trim()) {
      alert("A Title and the Main Content are required to save.");
      return;
    }

    if (activeTab === 'devotionals') {
      const current = storage.getDevotionals();
      const index = current.findIndex(d => d.id === editingItem.id);
      if (index > -1) current[index] = editingItem;
      else current.unshift(editingItem);
      storage.saveDevotionals(current);
      setDevotionals(current);
    } else {
      const current = storage.getSundaySchool();
      const index = current.findIndex(l => l.id === editingItem.id);
      if (index > -1) current[index] = editingItem;
      else current.unshift(editingItem);
      storage.saveSundaySchool(current);
      setLessons(current);
    }

    setEditingItem(null);
    onEntryAdded();
    alert("Saved Successfully.");
  };

  const handleAIExtract = async () => {
    if (!aiInput.trim()) return;
    setIsAIProcessing(true);
    try {
      const result = await extractDevotionalStructure(aiInput);
      if (result) {
        setEditingItem({
          ...editingItem,
          ...result,
          id: editingItem.id || Date.now().toString(),
          date: editingItem.date || new Date().toISOString().split('T')[0]
        });
        setAiInput('');
      }
    } catch (err) {
      alert("AI extraction failed. Please enter the data manually below.");
    } finally {
      setIsAIProcessing(false);
    }
  };

  return (
    <div className="pt-6 pb-24 animate-in fade-in">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-3xl font-bold serif-font text-stone-800">Admin Studio</h2>
          <p className="text-[10px] uppercase tracking-[0.3em] text-amber-800/60 font-black">Content Management</p>
        </div>
        {!editingItem && (
          <button 
            onClick={handleCreateNew}
            className="bg-amber-800 text-white px-6 py-4 rounded-[1.5rem] text-sm font-black shadow-xl shadow-amber-900/20 active:scale-95 transition-all flex items-center gap-2"
          >
            <span>+</span> NEW ENTRY
          </button>
        )}
      </div>

      <div className="flex gap-4 border-b border-stone-200 mb-8 overflow-x-auto no-scrollbar pb-1">
        <button 
          onClick={() => { setActiveTab('devotionals'); setEditingItem(null); }}
          className={`pb-4 px-2 text-xs font-black tracking-widest uppercase transition-all border-b-4 whitespace-nowrap ${activeTab === 'devotionals' ? 'border-amber-700 text-amber-700' : 'border-transparent text-stone-300'}`}
        >
          Daily Devotionals
        </button>
        <button 
          onClick={() => { setActiveTab('lessons'); setEditingItem(null); }}
          className={`pb-4 px-2 text-xs font-black tracking-widest uppercase transition-all border-b-4 whitespace-nowrap ${activeTab === 'lessons' ? 'border-indigo-700 text-indigo-700' : 'border-transparent text-stone-300'}`}
        >
          Sunday School Lessons
        </button>
      </div>

      {editingItem ? (
        <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-stone-100 space-y-8 animate-in zoom-in-95 duration-300 relative">
          <div className="flex justify-between items-start">
            <div>
              <h3 className="font-black text-2xl text-stone-800 serif-font">MANUAL EDITOR</h3>
              <p className="text-[10px] text-amber-700 font-bold uppercase tracking-widest">Editing: {editingItem.title || 'New Record'}</p>
            </div>
            <button onClick={() => setEditingItem(null)} className="p-3 bg-stone-100 rounded-full text-stone-400 hover:bg-stone-200 transition-colors">✕</button>
          </div>

          {activeTab === 'devotionals' && !editingItem.content && (
            <div className="p-6 bg-amber-50 rounded-[2rem] border border-amber-100 space-y-4 shadow-inner">
              <div className="flex items-center gap-2 mb-1">
                <ICONS.Sparkles />
                <label className="text-[10px] font-black text-amber-800 uppercase tracking-widest">AI Helper (Optional)</label>
              </div>
              <textarea 
                placeholder="Paste book text here for auto-fill..."
                className="w-full h-24 p-4 text-sm rounded-2xl border border-amber-200 bg-white/70 focus:bg-white focus:outline-none focus:ring-4 focus:ring-amber-500/10 transition-all shadow-sm"
                value={aiInput}
                onChange={(e) => setAiInput(e.target.value)}
              />
              <button 
                disabled={isAIProcessing || !aiInput}
                onClick={handleAIExtract}
                className="w-full py-4 bg-amber-800 text-white rounded-2xl text-xs font-black uppercase tracking-[0.2em] shadow-lg disabled:opacity-30 active:scale-[0.98] transition-all"
              >
                {isAIProcessing ? 'DIVINING STRUCTURE...' : 'EXTRACT DATA'}
              </button>
            </div>
          )}

          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">Title</label>
                <input 
                  type="text" 
                  value={editingItem.title}
                  onChange={e => setEditingItem({...editingItem, title: e.target.value})}
                  placeholder="Enter message title"
                  className="w-full p-5 rounded-3xl border-2 border-stone-100 bg-stone-50 focus:bg-white focus:border-amber-700/30 focus:ring-4 focus:ring-amber-500/5 transition-all outline-none text-xl font-bold serif-font"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">Publication Date</label>
                <input type="date" value={editingItem.date} onChange={e => setEditingItem({...editingItem, date: e.target.value})} className="w-full p-5 rounded-3xl border-2 border-stone-100 bg-stone-50 outline-none font-bold" />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">{activeTab === 'devotionals' ? 'Scripture Text' : 'Memory Verse'}</label>
              <textarea 
                rows={2}
                value={activeTab === 'devotionals' ? editingItem.scripture : editingItem.memoryVerse}
                onChange={e => activeTab === 'devotionals' ? setEditingItem({...editingItem, scripture: e.target.value}) : setEditingItem({...editingItem, memoryVerse: e.target.value})}
                placeholder="e.g. John 3:16"
                className="w-full p-5 rounded-3xl border-2 border-stone-100 bg-stone-50 italic serif-font text-lg outline-none focus:bg-white"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">Full Message Body</label>
              <textarea 
                value={editingItem.content}
                onChange={e => setEditingItem({...editingItem, content: e.target.value})}
                placeholder="Type or paste the devotional text here..."
                className="w-full h-80 p-6 rounded-[2rem] border-2 border-stone-100 bg-stone-50 focus:bg-white focus:border-amber-700/30 focus:ring-8 focus:ring-amber-500/5 transition-all outline-none serif-font text-lg leading-relaxed shadow-inner"
              />
            </div>

            {activeTab === 'devotionals' ? (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">Closing Prayer</label>
                  <textarea value={editingItem.prayer || ''} onChange={e => setEditingItem({...editingItem, prayer: e.target.value})} className="w-full p-5 rounded-3xl border-2 border-stone-100 bg-stone-50 text-base italic h-32 outline-none focus:bg-white" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">Meditation Note</label>
                  <textarea value={editingItem.meditation || ''} onChange={e => setEditingItem({...editingItem, meditation: e.target.value})} className="w-full p-5 rounded-3xl border-2 border-stone-100 bg-stone-50 text-base italic h-32 outline-none focus:bg-white" />
                </div>
              </div>
            ) : (
              <div className="space-y-2">
                <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-2">Discussion Questions (One per line)</label>
                <textarea 
                  value={editingItem.discussionQuestions?.join('\n')}
                  onChange={e => setEditingItem({...editingItem, discussionQuestions: e.target.value.split('\n').filter(q => q.trim())})}
                  className="w-full h-40 p-5 rounded-3xl border-2 border-stone-100 bg-stone-50 outline-none focus:bg-white"
                />
              </div>
            )}
          </div>

          <div className="flex flex-col gap-4 pt-4">
            <button onClick={handleSave} className="w-full py-6 bg-amber-800 text-white font-black uppercase tracking-[0.3em] rounded-[1.5rem] shadow-2xl active:scale-95 transition-all text-sm">
              SAVE CHANGES
            </button>
            <button onClick={() => setEditingItem(null)} className="w-full py-4 text-stone-400 font-bold uppercase tracking-widest text-xs">
              Discard & Go Back
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {(activeTab === 'devotionals' ? devotionals : lessons).length === 0 ? (
            <div className="py-20 text-center border-4 border-dashed border-stone-100 rounded-[3rem] text-stone-300">
              <p className="font-bold serif-font italic text-xl">No content added yet.</p>
            </div>
          ) : (
            (activeTab === 'devotionals' ? devotionals : lessons).map((item) => (
              <div key={item.id} className="p-6 bg-white border border-stone-100 rounded-[2rem] flex items-center justify-between group shadow-sm hover:shadow-md transition-all">
                <div className="flex-1">
                  <span className="text-[9px] font-black text-stone-300 uppercase tracking-widest block mb-1">{item.date}</span>
                  <h4 className="font-bold serif-font text-lg text-stone-800 line-clamp-1">{item.title}</h4>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => handleEdit(item)} className="px-4 py-3 bg-amber-50 text-amber-800 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-amber-100 active:scale-90 transition-all">
                    EDIT
                  </button>
                  <button onClick={() => handleDelete(item.id)} className="p-3 text-red-300 hover:text-red-600 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" /></svg>
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

export default AdminPanel;

import React, { useState, useEffect, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Link, useParams, useLocation, useNavigate, Navigate } from 'react-router-dom';
import { DevotionalEntry, SundaySchoolLesson, UserPreferences, ThemeMode } from './types.ts';
import { storage } from './services/storageService.ts';
import { ADMIN_SECRET_KEY, ICONS } from './constants.tsx';
import Layout from './components/Layout.tsx';
import DevotionalCard from './components/DevotionalCard.tsx';
import AdminPanel from './components/AdminPanel.tsx';

const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [sundayLessons, setSundayLessons] = useState<SundaySchoolLesson[]>([]);
  const [bookmarks, setBookmarks] = useState<string[]>(storage.getBookmarks());
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());
  const [isStandalone, setIsStandalone] = useState(false);
  const lastReminderRef = useRef<string | null>(null);

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
    setIsStandalone(window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone);
  }, []);

  useEffect(() => {
    const handleSync = () => {
      setBookmarks(storage.getBookmarks());
      setPrefs(storage.getPreferences());
      setIsAdmin(storage.getAdminMode());
      setDevotionals(storage.getDevotionals());
      setSundayLessons(storage.getSundaySchool());
    };
    window.addEventListener('storage', handleSync);
    window.addEventListener(storage.SYNC_EVENT, handleSync);
    return () => {
      window.removeEventListener('storage', handleSync);
      window.removeEventListener(storage.SYNC_EVENT, handleSync);
    };
  }, []);

  // Reminder Logic
  useEffect(() => {
    if (!prefs.notificationsEnabled) return;
    const intervalId = setInterval(() => {
      const now = new Date();
      const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      if (time === prefs.notificationTime && lastReminderRef.current !== time) {
        lastReminderRef.current = time;
        if (Notification.permission === 'granted') {
          new Notification("Spirit Meal", { 
            body: "Your daily spiritual meal is ready. Take a moment to feed your soul.",
            icon: '/icon-192.png'
          });
        }
      }
    }, 30000);
    return () => clearInterval(intervalId);
  }, [prefs.notificationsEnabled, prefs.notificationTime]);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const refreshData = () => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  };

  return (
    <Router>
      <Layout theme={prefs.theme} isAdmin={isAdmin}>
        <Routes>
          <Route path="/" element={devotionals[0] ? <DevotionalCard entry={devotionals[0]} theme={prefs.theme} fontSize={prefs.fontSize} /> : <p className="p-20 text-center opacity-40">Spirit Meal is preparing...</p>} />
          <Route path="/archive" element={<ArchiveView devotionals={devotionals} theme={prefs.theme} />} />
          <Route path="/lessons" element={<LessonsView lessons={sundayLessons} />} />
          <Route path="/lesson/:id" element={<SundaySchoolDetail lessons={sundayLessons} theme={prefs.theme} fontSize={prefs.fontSize} />} />
          <Route path="/devotional/:id" element={<DevotionalDetail devotionals={devotionals} theme={prefs.theme} fontSize={prefs.fontSize} />} />
          <Route path="/bookmarks" element={<BookmarksView devotionals={devotionals} bookmarks={bookmarks} />} />
          <Route path="/login" element={<LoginView onLogin={(success) => setIsAdmin(success)} />} />
          <Route path="/admin" element={isAdmin ? <AdminRoute isAdmin={isAdmin} refreshData={refreshData} /> : <Navigate to="/login" />} />
          <Route path="/settings" element={<SettingsView prefs={prefs} updatePrefs={updatePrefs} isAdmin={isAdmin} setIsAdmin={setIsAdmin} isStandalone={isStandalone} />} />
        </Routes>
      </Layout>
    </Router>
  );
};

