import { DevotionalEntry, SundaySchoolLesson, UserPreferences } from '../types';
import { INITIAL_DEVOTIONALS, INITIAL_SUNDAY_SCHOOL, DATA_VERSION } from '../constants';

const STORAGE_KEYS = {
  DEVOTIONALS: 'spirit_meal_devotionals',
  SUNDAY_SCHOOL: 'spirit_meal_sunday_school',
  PREFERENCES: 'spirit_meal_prefs',
  ADMIN_MODE: 'spirit_meal_admin',
  BOOKMARKS: 'spirit_meal_bookmarks',
  NOTES: 'spirit_meal_notes',
  REFLECTIONS_CACHE: 'spirit_meal_reflections',
  LAST_VERSION: 'spirit_meal_data_version'
};

// Custom event for same-window sync
const SYNC_EVENT = 'spirit_meal_sync';

const notifySync = () => {
  window.dispatchEvent(new CustomEvent(SYNC_EVENT));
};

// Check if we need to force-update users to the latest Master content
const hydrateMasterContent = () => {
  const currentSavedVersion = localStorage.getItem(STORAGE_KEYS.LAST_VERSION);
  if (currentSavedVersion !== DATA_VERSION) {
    console.log(`Updating Spirit Meal Content from ${currentSavedVersion} to ${DATA_VERSION}`);
    // Clear old data to force reload of INITIAL_... constants
    localStorage.removeItem(STORAGE_KEYS.DEVOTIONALS);
    localStorage.removeItem(STORAGE_KEYS.SUNDAY_SCHOOL);
    localStorage.setItem(STORAGE_KEYS.LAST_VERSION, DATA_VERSION);
    notifySync();
  }
};

// Run on service load
hydrateMasterContent();

export const storage = {
  SYNC_EVENT,
  resetToMaster: () => {
    localStorage.removeItem(STORAGE_KEYS.DEVOTIONALS);
    localStorage.removeItem(STORAGE_KEYS.SUNDAY_SCHOOL);
    localStorage.setItem(STORAGE_KEYS.LAST_VERSION, DATA_VERSION);
    notifySync();
  },
  getDevotionals: (): DevotionalEntry[] => {
    const data = localStorage.getItem(STORAGE_KEYS.DEVOTIONALS);
    return data ? JSON.parse(data) : INITIAL_DEVOTIONALS;
  },
  saveDevotionals: (devotionals: DevotionalEntry[]) => {
    localStorage.setItem(STORAGE_KEYS.DEVOTIONALS, JSON.stringify(devotionals));
    notifySync();
  },
  deleteDevotional: (id: string) => {
    const items = storage.getDevotionals().filter(i => i.id !== id);
    storage.saveDevotionals(items);
  },
  getSundaySchool: (): SundaySchoolLesson[] => {
    const data = localStorage.getItem(STORAGE_KEYS.SUNDAY_SCHOOL);
    return data ? JSON.parse(data) : INITIAL_SUNDAY_SCHOOL;
  },
  saveSundaySchool: (lessons: SundaySchoolLesson[]) => {
    localStorage.setItem(STORAGE_KEYS.SUNDAY_SCHOOL, JSON.stringify(lessons));
    notifySync();
  },
  deleteSundaySchool: (id: string) => {
    const items = storage.getSundaySchool().filter(i => i.id !== id);
    storage.saveSundaySchool(items);
  },
  getPreferences: (): UserPreferences => {
    const data = localStorage.getItem(STORAGE_KEYS.PREFERENCES);
    return data ? JSON.parse(data) : {
      theme: 'light',
      notificationsEnabled: false,
      notificationTime: '07:00',
      fontSize: 'base'
    };
  },
  savePreferences: (prefs: UserPreferences) => {
    localStorage.setItem(STORAGE_KEYS.PREFERENCES, JSON.stringify(prefs));
    notifySync();
  },
  getAdminMode: (): boolean => {
    return localStorage.getItem(STORAGE_KEYS.ADMIN_MODE) === 'true';
  },
  setAdminMode: (active: boolean) => {
    localStorage.setItem(STORAGE_KEYS.ADMIN_MODE, active ? 'true' : 'false');
    notifySync();
  },
  getBookmarks: (): string[] => {
    const data = localStorage.getItem(STORAGE_KEYS.BOOKMARKS);
    return data ? JSON.parse(data) : [];
  },
  saveBookmarks: (ids: string[]) => {
    localStorage.setItem(STORAGE_KEYS.BOOKMARKS, JSON.stringify(ids));
    notifySync();
  },
  toggleBookmark: (id: string): boolean => {
    const bookmarks = storage.getBookmarks();
    const index = bookmarks.indexOf(id);
    let isAdded = false;

    if (index === -1) {
      bookmarks.push(id);
      isAdded = true;
    } else {
      bookmarks.splice(index, 1);
      isAdded = false;
    }

    storage.saveBookmarks(bookmarks);
    return isAdded;
  },
  getNotes: (): Record<string, string> => {
    const data = localStorage.getItem(STORAGE_KEYS.NOTES);
    return data ? JSON.parse(data) : {};
  },
  getNote: (id: string): string => {
    return storage.getNotes()[id] || '';
  },
  saveNote: (id: string, note: string) => {
    const notes = storage.getNotes();
    if (!note.trim()) {
      delete notes[id];
    } else {
      notes[id] = note;
    }
    localStorage.setItem(STORAGE_KEYS.NOTES, JSON.stringify(notes));
    notifySync();
  },
  getReflectionsCache: (id: string): string[] | null => {
    const data = localStorage.getItem(STORAGE_KEYS.REFLECTIONS_CACHE);
    if (!data) return null;
    const cache = JSON.parse(data);
    return cache[id] || null;
  },
  saveReflectionsToCache: (id: string, reflections: string[]) => {
    const data = localStorage.getItem(STORAGE_KEYS.REFLECTIONS_CACHE);
    const cache = data ? JSON.parse(data) : {};
    cache[id] = reflections;
    localStorage.setItem(STORAGE_KEYS.REFLECTIONS_CACHE, JSON.stringify(cache));
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { HashRouter as Router, Routes, Route, Link, useParams, useLocation, useNavigate, Navigate } from 'react-router-dom';
import { DevotionalEntry, SundaySchoolLesson, UserPreferences, ThemeMode } from './types.ts';
import { storage } from './services/storageService.ts';
import { ADMIN_SECRET_KEY, ICONS } from './constants.tsx';
import Layout from './components/Layout.tsx';
import DevotionalCard from './components/DevotionalCard.tsx';
import AdminPanel from './components/AdminPanel.tsx';

const App: React.FC = () => {
  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>([]);
  const [sundayLessons, setSundayLessons] = useState<SundaySchoolLesson[]>([]);
  const [bookmarks, setBookmarks] = useState<string[]>(storage.getBookmarks());
  const [prefs, setPrefs] = useState<UserPreferences>(storage.getPreferences());
  const [isAdmin, setIsAdmin] = useState(storage.getAdminMode());
  const [isStandalone, setIsStandalone] = useState(false);
  const lastReminderRef = useRef<string | null>(null);

  useEffect(() => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
    setIsStandalone(window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone);
  }, []);

  useEffect(() => {
    const handleSync = () => {
      setBookmarks(storage.getBookmarks());
      setPrefs(storage.getPreferences());
      setIsAdmin(storage.getAdminMode());
      setDevotionals(storage.getDevotionals());
      setSundayLessons(storage.getSundaySchool());
    };
    window.addEventListener('storage', handleSync);
    window.addEventListener(storage.SYNC_EVENT, handleSync);
    return () => {
      window.removeEventListener('storage', handleSync);
      window.removeEventListener(storage.SYNC_EVENT, handleSync);
    };
  }, []);

  // Reminder Logic
  useEffect(() => {
    if (!prefs.notificationsEnabled) return;
    const intervalId = setInterval(() => {
      const now = new Date();
      const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
      if (time === prefs.notificationTime && lastReminderRef.current !== time) {
        lastReminderRef.current = time;
        if (Notification.permission === 'granted') {
          new Notification("Spirit Meal", { 
            body: "Your daily spiritual meal is ready. Take a moment to feed your soul.",
            icon: '/icon-192.png'
          });
        }
      }
    }, 30000);
    return () => clearInterval(intervalId);
  }, [prefs.notificationsEnabled, prefs.notificationTime]);

  const updatePrefs = (newPrefs: Partial<UserPreferences>) => {
    const updated = { ...prefs, ...newPrefs };
    setPrefs(updated);
    storage.savePreferences(updated);
  };

  const refreshData = () => {
    setDevotionals(storage.getDevotionals());
    setSundayLessons(storage.getSundaySchool());
  };

  return (
    <Router>
      <Layout theme={prefs.theme} isAdmin={isAdmin}>
        <Routes>
          <Route path="/" element={devotionals[0] ? <DevotionalCard entry={devotionals[0]} theme={prefs.theme} fontSize={prefs.fontSize} /> : <p className="p-20 text-center opacity-40">Spirit Meal is preparing...</p>} />
          <Route path="/archive" element={<ArchiveView devotionals={devotionals} theme={prefs.theme} />} />
          <Route path="/lessons" element={<LessonsView lessons={sundayLessons} />} />
          <Route path="/lesson/:id" element={<SundaySchoolDetail lessons={sundayLessons} theme={prefs.theme} fontSize={prefs.fontSize} />} />
          <Route path="/devotional/:id" element={<DevotionalDetail devotionals={devotionals} theme={prefs.theme} fontSize={prefs.fontSize} />} />
          <Route path="/bookmarks" element={<BookmarksView devotionals={devotionals} bookmarks={bookmarks} />} />
          <Route path="/login" element={<LoginView onLogin={(success) => setIsAdmin(success)} />} />
          <Route path="/admin" element={isAdmin ? <AdminRoute isAdmin={isAdmin} refreshData={refreshData} /> : <Navigate to="/login" />} />
          <Route path="/settings" element={<SettingsView prefs={prefs} updatePrefs={updatePrefs} isAdmin={isAdmin} setIsAdmin={setIsAdmin} isStandalone={isStandalone} />} />
        </Routes>
      </Layout>
    </Router>
  );
};

// --- SUB-COMPONENTS ---

const LoginView = ({ onLogin }: { onLogin: (s: boolean) => void }) => {
  const [key, setKey] = useState('');
  const [error, setError] = useState(false);
  const navigate = useNavigate();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (key === ADMIN_SECRET_KEY) {
      storage.setAdminMode(true);
      onLogin(true);
      navigate('/admin');
    } else {
      setError(true);
      setKey('');
    }
  };

  return (
    <div className="pt-20 px-6 max-w-sm mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4">
      <div className="text-center space-y-2">
        <h2 className="text-3xl font-bold serif-font">Admin Studio</h2>
        <p className="text-xs text-stone-400 font-bold uppercase tracking-widest">Entry Restricted</p>
      </div>
      <form onSubmit={handleLogin} className="space-y-4">
        <div className="space-y-1">
          <label className="text-[10px] font-black uppercase tracking-widest text-stone-400 ml-2">Master Access Key</label>
          <input 
            type="password" 
            autoFocus
            value={key}
            onChange={(e) => {setKey(e.target.value); setError(false);}}
            placeholder="••••••••••••"
            className={`w-full p-5 rounded-3xl border-2 bg-stone-50 outline-none transition-all text-center tracking-[0.5em] font-black ${error ? 'border-red-200 focus:border-red-400' : 'border-stone-100 focus:border-amber-700/30'}`}
          />
        </div>
        {error && <p className="text-center text-red-500 text-[10px] font-bold uppercase animate-bounce">Access Denied</p>}
        <button type="submit" className="w-full py-5 bg-amber-800 text-white rounded-[1.5rem] font-black uppercase tracking-[0.2em] shadow-xl shadow-amber-900/20 active:scale-95 transition-all">
          Unlock Studio
        </button>
      </form>
      <p className="text-center text-[10px] text-stone-300 italic">Access is reserved for authorized ministry administrators only.</p>
    </div>
  );
};

const SettingsView = ({ prefs, updatePrefs, isAdmin, setIsAdmin, isStandalone }: any) => {
  const navigate = useNavigate();
  return (
    <div className="pt-6 space-y-8 pb-20">
      <h2 className="text-2xl font-bold serif-font">Settings</h2>

      <section className="space-y-4">
        <div className="flex items-center gap-2">
           <ICONS.Settings />
           <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Daily Reminders</h3>
        </div>
        <div className="p-6 rounded-3xl bg-white border border-stone-100 shadow-sm space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="font-bold">Enable Alerts</p>
              <p className="text-xs text-stone-500">Nudge me for my morning meal</p>
            </div>
            <button onClick={() => updatePrefs({ notificationsEnabled: !prefs.notificationsEnabled })} className={`w-14 h-7 rounded-full relative transition-all shadow-inner ${prefs.notificationsEnabled ? 'bg-amber-600' : 'bg-stone-200'}`}>
              <div className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow-sm transition-all ${prefs.notificationsEnabled ? 'left-8' : 'left-1'}`} />
            </button>
          </div>

          {prefs.notificationsEnabled && (
            <div className="space-y-6">
              <input type="time" value={prefs.notificationTime} onChange={e => updatePrefs({ notificationTime: e.target.value })} className="w-full p-4 rounded-2xl border bg-stone-50 font-bold text-center text-2xl" />
              {!isStandalone && <p className="p-4 bg-amber-50 rounded-2xl text-[10px] text-amber-900 italic">Note: For persistent alerts on mobile, use 'Add to Home Screen'.</p>}
            </div>
          )}
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex items-center gap-2">
           <div className="w-6 h-6 rounded-full bg-stone-200" />
           <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Theme</h3>
        </div>
        <div className="grid grid-cols-3 gap-2">
          {(['light', 'sepia', 'dark'] as const).map(m => (
            <button key={m} onClick={() => updatePrefs({ theme: m })} className={`py-4 rounded-2xl border-2 capitalize text-sm font-bold ${prefs.theme === m ? 'border-amber-600 bg-amber-50 text-amber-900 shadow-md' : 'border-stone-100 bg-white text-stone-500'}`}>
              {m}
            </button>
          ))}
        </div>
      </section>

      <section className="space-y-4 pt-4 border-t border-stone-100">
        <h3 className="text-xs font-bold uppercase tracking-widest text-stone-400">Advanced</h3>
        <button 
          onClick={() => { if(confirm("This will restore the app to the Master version. Your local drafts will be lost. Continue?")) { storage.resetToMaster(); alert("App Restored!"); window.location.reload(); } }}
          className="w-full p-4 border-2 border-stone-100 text-stone-500 font-bold text-[10px] uppercase rounded-2xl hover:bg-stone-50"
        >
          Restore Master Content
        </button>
      </section>

      {isAdmin ? (
        <div className="space-y-3 pt-6">
          <button onClick={() => navigate('/admin')} className="w-full py-5 bg-stone-800 text-white rounded-[1.5rem] font-black uppercase tracking-[0.2em] text-xs">
            Open Admin Studio
          </button>
          <button onClick={() => { if(confirm("Logout from Admin?")) { storage.setAdminMode(false); setIsAdmin(false); navigate('/'); } }} className="w-full py-5 border-2 border-stone-200 text-stone-400 font-bold uppercase tracking-widest text-[10px] rounded-[1.5rem]">
            Logout Administrator
          </button>
        </div>
      ) : (
        <button onClick={() => navigate('/login')} className="w-full py-5 border-2 border-dashed border-stone-200 text-stone-400 text-xs font-bold uppercase tracking-[0.2em] rounded-2xl hover:border-amber-300 hover:text-amber-800 transition-all">
          Admin Portal Access
        </button>
      )}
    </div>
  );
};

const AdminRoute = ({ refreshData }: { isAdmin: boolean, refreshData: () => void }) => {
  const location = useLocation();
  const editId = location.state?.editId;
  return <AdminPanel onEntryAdded={refreshData} editId={editId} />;
};

const ArchiveView = ({ devotionals, theme }: any) => (
  <div className="pt-6 space-y-4">
    <h2 className="text-2xl font-bold serif-font mb-4">Library</h2>
    {devotionals.length === 0 ? <p className="text-center py-10 opacity-40 italic">Library is empty</p> : devotionals.map((d: any) => (
      <Link key={d.id} to={`/devotional/${d.id}`} className={`block p-4 rounded-2xl border transition-all hover:translate-x-1 ${theme === 'dark' ? 'bg-stone-800 border-stone-700' : 'bg-white border-stone-100 shadow-sm'}`}>
        <span className="text-[10px] font-bold text-amber-700 uppercase tracking-widest">{d.date}</span>
        <h3 className="font-bold text-lg serif-font">{d.title}</h3>
      </Link>
    ))}
  </div>
);

const LessonsView = ({ lessons }: any) => (
  <div className="pt-6 space-y-4">
    <h2 className="text-2xl font-bold serif-font mb-4">Sunday School</h2>
    {lessons.length === 0 ? <p className="text-center py-10 opacity-40 italic">No lessons found</p> : lessons.map((l: any) => (
      <Link key={l.id} to={`/lesson/${l.id}`} className="block p-5 rounded-3xl bg-white border border-indigo-100 shadow-sm transition-all hover:translate-x-1">
        <span className="text-[10px] font-bold text-indigo-700 uppercase tracking-widest">{l.topic}</span>
        <h3 className="font-bold text-lg serif-font text-indigo-950">{l.title}</h3>
      </Link>
    ))}
  </div>
);

const BookmarksView = ({ devotionals, bookmarks }: any) => {
  const list = devotionals.filter((d: any) => bookmarks.includes(d.id));
  return (
    <div className="pt-6 space-y-4">
      <h2 className="text-2xl font-bold serif-font mb-4">Saved Meals</h2>
      {list.length === 0 ? <p className="text-center py-20 opacity-40 italic">No saved meals found</p> : list.map((d: any) => (
        <Link key={d.id} to={`/devotional/${d.id}`} className="block p-5 rounded-3xl bg-white border border-amber-100 shadow-sm flex justify-between items-center group">
          <h3 className="font-bold serif-font group-hover:text-amber-800 transition-colors">{d.title}</h3>
          <ICONS.Bookmark />
        </Link>
      ))}
    </div>
  );
};

const DevotionalDetail = ({ devotionals, theme, fontSize }: any) => {
  const { id } = useParams();
  const entry = devotionals.find((d: any) => d.id === id);
  if (!entry) return <p className="p-20 text-center opacity-40">Entry not found</p>;
  return <DevotionalCard entry={entry} theme={theme} fontSize={fontSize} />;
};

const SundaySchoolDetail = ({ lessons, theme, fontSize }: any) => {
  const { id } = useParams();
  const lesson = lessons.find((l: any) => l.id === id);
  if (!lesson) return <p className="p-20 text-center opacity-40">Lesson not found</p>;
  const sizeClass = { sm: 'text-sm', base: 'text-base', lg: 'text-lg', xl: 'text-xl' }[fontSize as any] || 'text-base';
  return (
    <div className="py-8 animate-in fade-in slide-in-from-bottom-2">
      <span className="text-xs font-bold uppercase tracking-widest text-indigo-700 mb-2 block">{lesson.topic}</span>
      <h2 className="text-3xl md:text-4xl font-bold serif-font mb-6 leading-tight">{lesson.title}</h2>
      {lesson.imageUrl && (
        <div className="mb-8 rounded-3xl overflow-hidden shadow-lg aspect-video">
          <img src={lesson.imageUrl} alt={lesson.title} className="w-full h-full object-cover" />
        </div>
      )}
      <div className="p-6 rounded-2xl bg-indigo-50 border-l-4 border-indigo-600 mb-8">
        <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-800 mb-1">Memory Verse</p>
        <p className="serif-font italic text-lg text-indigo-900">"{lesson.memoryVerse}"</p>
      </div>
      <div className={`serif-font leading-relaxed ${sizeClass} ${theme === 'dark' ? 'text-stone-300' : 'text-stone-700'} mb-12`}>
        {lesson.content.split('\n').map((p: string, i: number) => <p key={i} className="mb-4">{p}</p>)}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { extractDevotionalStructure } from '../services/geminiService.ts';
import { DevotionalEntry, SundaySchoolLesson } from '../types.ts';
import { storage } from '../services/storageService.ts';
import { ICONS, INITIAL_DEVOTIONALS } from '../constants.tsx';

interface AdminPanelProps {
  onEntryAdded: () => void;
  editId?: string | null;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onEntryAdded, editId }) => {
  const [activeTab, setActiveTab] = useState<'devotionals' | 'lessons'>('devotionals');
  const [editingItem, setEditingItem] = useState<any | null>(null);

  const [devotionals, setDevotionals] = useState<DevotionalEntry[]>(storage.getDevotionals());
  const [lessons, setLessons] = useState<SundaySchoolLesson[]>(storage.getSundaySchool());

  const isLocalOnly = devotionals.length !== INITIAL_DEVOTIONALS.length || 
                      JSON.stringify(devotionals) !== JSON.stringify(INITIAL_DEVOTIONALS);

  useEffect(() => {
    if (editId) {
      const dev = devotionals.find(d => d.id === editId);
      if (dev) {
        setActiveTab('devotionals');
        // Convert tags array to string for editing
        setEditingItem({ ...dev, tagsString: dev.tags?.join(', ') || '' });
        return;
      }
      const lesson = lessons.find(l => l.id === editId);
      if (lesson) {
        setActiveTab('lessons');
        // Convert questions array to newline string for editing
        setEditingItem({ ...lesson, questionsString: lesson.discussionQuestions?.join('\n') || '' });
      }
    }
  }, [editId, devotionals, lessons]);

  const handleCreateNew = () => {
    const id = Date.now().toString();
    const date = new Date().toISOString().split('T')[0];

    if (activeTab === 'devotionals') {
      setEditingItem({
        id, date, title: '', scripture: '', content: '', prayer: '', meditation: '', imageUrl: '', tags: [], tagsString: ''
      });
    } else {
      setEditingItem({
        id, date, title: '', topic: '', memoryVerse: '', content: '', imageUrl: '', discussionQuestions: [], questionsString: ''
      });
    }
  };

  const handleEdit = (item: any) => {
    if (activeTab === 'devotionals') {
      setEditingItem({ ...item, tagsString: item.tags?.join(', ') || '' });
    } else {
      setEditingItem({ ...item, questionsString: item.discussionQuestions?.join('\n') || '' });
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Delete this entry permanently?')) {
      if (activeTab === 'devotionals') {
        storage.deleteDevotional(id);
        setDevotionals(storage.getDevotionals());
      } else {
        storage.deleteSundaySchool(id);
        setLessons(storage.getSundaySchool());
      }
      onEntryAdded();
    }
  };

  const handleSave = () => {
    if (!editingItem.title?.trim() || !editingItem.content?.trim()) {
      alert("A Title and Content are required.");
      return;
    }

    const itemToSave = { ...editingItem };

    if (activeTab === 'devotionals') {
      // Clean up tags
      itemToSave.tags = itemToSave.tagsString
        ? itemToSave.tagsString.split(',').map((s: string) => s.trim()).filter(Boolean)
        : [];
      delete itemToSave.tagsString;

      const current = storage.getDevotionals();
      const index = current.findIndex(d => d.id === itemToSave.id);
      if (index > -1) current[index] = itemToSave;
      else current.unshift(itemToSave);
      storage.saveDevotionals(current);
      setDevotionals(current);
    } else {
      // Clean up questions
      itemToSave.discussionQuestions = itemToSave.questionsString
        ? itemToSave.questionsString.split('\n').map((s: string) => s.trim()).filter(Boolean)
        : [];
      delete itemToSave.questionsString;

      const current = storage.getSundaySchool();
      const index = current.findIndex(l => l.id === itemToSave.id);
      if (index > -1) current[index] = itemToSave;
      else current.unshift(itemToSave);
      storage.saveSundaySchool(current);
      setLessons(current);
    }

    setEditingItem(null);
    onEntryAdded();
    alert("Saved Locally! To update globally, export and send to developer.");
  };

  const handleExportData = () => {
    const data = {
      devotionals: storage.getDevotionals(),
      lessons: storage.getSundaySchool(),
      timestamp: new Date().toISOString()
    };
    const json = JSON.stringify(data, null, 2);
    const exportWindow = window.open("", "_blank");
    if (exportWindow) {
      exportWindow.document.write(`<html><body style="padding:40px;font-family:sans-serif;background:#fafaf9;"><h1>Master Export</h1><p>Copy this text and send it to your developer to update the global version of the app.</p><textarea style="width:100%;height:70vh;padding:20px;border-radius:12px;border:1px solid #e7e5e4;font-family:monospace;font-size:12px;">${json}</textarea></body></html>`);
    }
  };

  return (
    <div className="pt-6 pb-24 animate-in fade-in">
      {!editingItem && (
        <div className={`p-6 rounded-[2.5rem] mb-10 border transition-all ${isLocalOnly ? 'bg-amber-50 border-amber-200 shadow-lg' : 'bg-stone-50 border-stone-100'}`}>
          <div className="flex items-center gap-3 mb-4">
            <div className={`w-3 h-3 rounded-full ${isLocalOnly ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`} />
            <h3 className="font-black text-xs uppercase tracking-widest text-stone-600">
              {isLocalOnly ? 'Unpublished Changes' : 'Synced with Global Master'}
            </h3>
          </div>
          <div className="flex flex-col md:flex-row items-center justify-between gap-6">
            <p className="text-sm text-stone-500 max-w-md">Your edits are saved only on this device. Click publish to generate a data file for the global update.</p>
            <button onClick={handleExportData} className="w-full md:w-auto px-8 py-4 bg-amber-800 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-amber-900 transition-colors">PUBLISH DATA</button>
          </div>
        </div>
      )}

      {editingItem ? (
        <div className="bg-white rounded-[3rem] p-8 md:p-12 shadow-2xl space-y-10 border border-stone-100">
          <div className="flex justify-between items-center border-b border-stone-50 pb-6">
            <div>
              <h3 className="font-black text-2xl serif-font text-stone-800">Editing {activeTab === 'devotionals' ? 'Spirit Meal' : 'Sunday Lesson'}</h3>
              <p className="text-[10px] font-bold uppercase tracking-widest text-stone-400 mt-1">ID: {editingItem.id}</p>
            </div>
            <button onClick={() => setEditingItem(null)} className="p-3 bg-stone-50 rounded-full text-stone-400 hover:text-stone-600 transition-colors">✕</button>
          </div>

          <div className="space-y-10">
            {/* SECTION 1: CORE DETAILS */}
            <div className="space-y-6">
              <h4 className="text-[10px] font-black uppercase tracking-widest text-amber-700">Primary Content</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Title</label>
                  <input type="text" placeholder="Entry Title" value={editingItem.title} onChange={e => setEditingItem({...editingItem, title: e.target.value})} className="w-full p-4 rounded-2xl border-2 border-stone-100 bg-stone-50 font-bold focus:border-amber-200 outline-none transition-all" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Publication Date</label>
                  <input type="date" value={editingItem.date} onChange={e => setEditingItem({...editingItem, date: e.target.value})} className="w-full p-4 rounded-2xl border-2 border-stone-100 bg-stone-50 font-bold focus:border-amber-200 outline-none transition-all" />
                </div>
              </div>

              {activeTab === 'lessons' && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Topic / Category</label>
                  <input type="text" placeholder="e.g. Divine Provision" value={editingItem.topic} onChange={e => setEditingItem({...editingItem, topic: e.target.value})} className="w-full p-4 rounded-2xl border-2 border-stone-100 bg-stone-50 font-bold focus:border-amber-200 outline-none transition-all" />
                </div>
              )}
            </div>

            {/* SECTION 2: SCRIPTURE & VISUALS */}
            <div className="space-y-6 pt-6 border-t border-stone-50">
               <h4 className="text-[10px] font-black uppercase tracking-widest text-amber-700">Scriptural Foundation</h4>
               <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-stone-400 ml-2">{activeTab === 'devotionals' ? 'Scripture Reference' : 'Memory Verse'}</label>
                  <input 
                    type="text" 
                    placeholder={activeTab === 'devotionals' ? "e.g. Acts 21:8-10" : "e.g. Hebrews 11:1"} 
                    value={activeTab === 'devotionals' ? editingItem.scripture : editingItem.memoryVerse} 
                    onChange={e => setEditingItem(activeTab === 'devotionals' ? {...editingItem, scripture: e.target.value} : {...editingItem, memoryVerse: e.target.value})} 
                    className="w-full p-4 rounded-2xl border-2 border-stone-100 bg-stone-50 font-medium italic serif-font text-lg focus:border-amber-200 outline-none transition-all" 
                  />
               </div>

               <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-stone-400 ml-2">Cover Image URL</label>
                <input type="text" placeholder="https://picsum.photos/..." value={editingItem.imageUrl} onChange={e => setEditingItem({...editingItem, imageUrl: e.target.value})} className="w-full p-4 rounded-2xl border-2 border-stone-100 bg-stone-50 text-sm focus:border-amber-200 outline-none transition-all" />
                {editingItem.imageUrl && (
                  <div className="mt-2 rounded-2xl overflow-hidden aspect-video border-2 border-stone-100 shadow-inner bg-stone-100">
                    <img src={editingItem.imageUrl} alt="Preview" className="w-full h-full object-cover" />
